//! Small re-implementations of Java / Spring / Commons behaviours the
//! original relies on (number formatting, Locale handling, BeanUtils
//! conversions, Spring's path variable parsing, HashMap iteration order).

/// `java.lang.Double.toString(double)`.
pub fn double_to_string(d: f64) -> String {
    if d.is_nan() {
        return "NaN".into();
    }
    if d.is_infinite() {
        return if d > 0.0 { "Infinity".into() } else { "-Infinity".into() };
    }
    if d == 0.0 {
        return if d.is_sign_negative() { "-0.0".into() } else { "0.0".into() };
    }
    // shortest round-trip digits
    let s = format!("{:e}", d.abs());
    let (mant, exp) = s.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    let neg = if d < 0.0 { "-" } else { "" };
    let a = d.abs();
    if (1e-3..1e7).contains(&a) {
        // plain notation
        let point = exp + 1; // number of digits before the decimal point
        let mut out = String::new();
        if point <= 0 {
            out.push_str("0.");
            for _ in 0..(-point) {
                out.push('0');
            }
            out.push_str(&digits);
        } else {
            let p = point as usize;
            if digits.len() <= p {
                out.push_str(&digits);
                for _ in digits.len()..p {
                    out.push('0');
                }
                out.push_str(".0");
            } else {
                out.push_str(&digits[..p]);
                out.push('.');
                out.push_str(&digits[p..]);
            }
        }
        format!("{}{}", neg, out)
    } else {
        let first = &digits[..1];
        let rest = if digits.len() > 1 { &digits[1..] } else { "0" };
        format!("{}{}.{}E{}", neg, first, rest, exp)
    }
}

/// Java `Character.isDigit` approximation (ASCII + Unicode decimal digits).
fn is_digit(c: char) -> bool {
    c.is_ascii_digit() || (c.is_numeric() && c.to_digit(10).is_some())
}

/// commons-lang3 `NumberUtils.isParsable`.
pub fn is_parsable(s: &str) -> bool {
    if s.is_empty() || s.ends_with('.') {
        return false;
    }
    let body = if let Some(r) = s.strip_prefix('-') {
        if r.is_empty() {
            return false;
        }
        r
    } else {
        s
    };
    let mut points = 0;
    for c in body.chars() {
        if c == '.' {
            points += 1;
            if points > 1 {
                return false;
            }
        } else if !is_digit(c) {
            return false;
        }
    }
    true
}

/// commons-lang3 `NumberUtils.isDigits`.
pub fn is_digits(s: &str) -> bool {
    !s.is_empty() && s.chars().all(is_digit)
}

/// `Integer.valueOf(String)` / `Integer.parseInt`.
pub fn java_parse_int(s: &str) -> Option<i32> {
    let b = s.as_bytes();
    if b.is_empty() {
        return None;
    }
    let (neg, digits) = match b[0] {
        b'-' => (true, &s[1..]),
        b'+' => (false, &s[1..]),
        _ => (false, s),
    };
    if digits.is_empty() || !digits.bytes().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let mut v: i64 = 0;
    for c in digits.bytes() {
        v = v * 10 + (c - b'0') as i64;
        if v > (i32::MAX as i64) + 1 {
            return None;
        }
    }
    let v = if neg { -v } else { v };
    if v < i32::MIN as i64 || v > i32::MAX as i64 {
        return None;
    }
    Some(v as i32)
}

/// `Long.parseLong`.
pub fn java_parse_long(s: &str) -> Option<i64> {
    let b = s.as_bytes();
    if b.is_empty() {
        return None;
    }
    let (neg, digits) = match b[0] {
        b'-' => (true, &s[1..]),
        b'+' => (false, &s[1..]),
        _ => (false, s),
    };
    if digits.is_empty() || !digits.bytes().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let mut v: i128 = 0;
    for c in digits.bytes() {
        v = v * 10 + (c - b'0') as i128;
        if v > (i64::MAX as i128) + 1 {
            return None;
        }
    }
    let v = if neg { -v } else { v };
    if v < i64::MIN as i128 || v > i64::MAX as i128 {
        return None;
    }
    Some(v as i64)
}

/// `Double.parseDouble` (whitespace trimmed, optional d/f suffix, NaN/Infinity).
pub fn java_parse_double(s: &str) -> Option<f64> {
    let t = s.trim_matches(|c: char| c <= ' ');
    if t.is_empty() {
        return None;
    }
    let (sign, body) = match t.as_bytes()[0] {
        b'-' => (-1.0, &t[1..]),
        b'+' => (1.0, &t[1..]),
        _ => (1.0, t),
    };
    if body == "NaN" {
        return Some(f64::NAN);
    }
    if body == "Infinity" {
        return Some(sign * f64::INFINITY);
    }
    let body = body
        .strip_suffix(['d', 'D', 'f', 'F'])
        .unwrap_or(body);
    if body.is_empty() {
        return None;
    }
    // only decimal floating literals: digits, optional '.', optional exponent
    let bytes = body.as_bytes();
    let mut i = 0;
    let mut nd = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
        nd += 1;
    }
    if i < bytes.len() && bytes[i] == b'.' {
        i += 1;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
            nd += 1;
        }
    }
    if nd == 0 {
        return None;
    }
    if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
        i += 1;
        if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
            i += 1;
        }
        let st = i;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
        if i == st {
            return None;
        }
    }
    if i != bytes.len() {
        return None;
    }
    body.parse::<f64>().ok().map(|v| sign * v)
}

/// Value of a BeanUtils `ConvertUtils.convert(String, type)` call with the
/// standard converters (defaults instead of exceptions).
#[derive(Debug, Clone, PartialEq)]
pub enum Conv {
    Str(String),
    Int(i32),
    Bool(bool),
    Dbl(f64),
}

pub fn beanutils_int(s: &str) -> i32 {
    let t = s.trim();
    if t.is_empty() {
        return 0;
    }
    java_parse_int(t).unwrap_or(0)
}

pub fn beanutils_double(s: &str) -> f64 {
    let t = s.trim();
    if t.is_empty() {
        return 0.0;
    }
    java_parse_double(t).unwrap_or(0.0)
}

pub fn beanutils_bool(s: &str) -> bool {
    let l = s.to_lowercase();
    matches!(l.as_str(), "true" | "yes" | "y" | "on" | "1")
}

/// Spring `NumberUtils.parseNumber(text, Integer.class)` as used for
/// `@PathVariable Integer id`.
pub fn spring_parse_int(s: &str) -> Option<i32> {
    let t: String = s.chars().filter(|c| !c.is_whitespace()).collect();
    let (neg, rest) = if let Some(r) = t.strip_prefix('-') {
        (true, r.to_string())
    } else {
        (false, t.clone())
    };
    let hex = rest.starts_with("0x") || rest.starts_with("0X") || rest.starts_with('#');
    if hex {
        let digits = if rest.starts_with('#') { &rest[1..] } else { &rest[2..] };
        if digits.is_empty() || digits.starts_with('-') || digits.starts_with('+') {
            return None;
        }
        let v = i64::from_str_radix(digits, 16).ok()?;
        let v = if neg { -v } else { v };
        if v < i32::MIN as i64 || v > i32::MAX as i64 {
            return None;
        }
        return Some(v as i32);
    }
    java_parse_int(&t)
}

// ---------------------------------------------------------------------------
// java.util.Locale

fn lower(s: &str) -> String {
    s.to_ascii_lowercase()
}
fn upper(s: &str) -> String {
    s.to_ascii_uppercase()
}

/// `new Locale(language, country, variant).toString()`
pub fn locale_to_string(language: &str, country: &str, variant: &str) -> String {
    let mut lang = lower(language);
    lang = match lang.as_str() {
        "he" => "iw".into(),
        "yi" => "ji".into(),
        "id" => "in".into(),
        _ => lang,
    };
    let region = upper(country);
    let l = !lang.is_empty();
    let r = !region.is_empty();
    let v = !variant.is_empty();
    let mut out = lang.clone();
    if r || (l && v) {
        out.push('_');
        out.push_str(&region);
    }
    if v && (l || r) {
        out.push('_');
        out.push_str(variant);
    }
    out
}

/// Jackson's `Locale` deserialization from a string.
pub fn locale_from_jackson(value: &str) -> String {
    if value.is_empty() {
        return String::new();
    }
    let first_sep = |s: &str| s.find(['-', '_']);
    match first_sep(value) {
        None => locale_to_string(value, "", ""),
        Some(ix) => {
            let first = &value[..ix];
            let rest = &value[ix + 1..];
            match first_sep(rest) {
                None => locale_to_string(first, rest, ""),
                Some(ix2) => {
                    let second = &rest[..ix2];
                    locale_to_string(first, second, &rest[ix2 + 1..])
                }
            }
        }
    }
}

/// Hibernate's `LocaleType.fromString` followed by `toString`.
pub fn locale_from_db(s: &str) -> String {
    if s.is_empty() {
        return String::new();
    }
    let chars: Vec<char> = s.chars().collect();
    let mut sep_found = false;
    let mut position = 0usize;
    let mut lang = String::new();
    for i in 0..chars.len() {
        if chars[i] == '_' {
            if !sep_found {
                lang = chars[position..i].iter().collect();
                position = i + 1;
            } else {
                let country: String = chars[position..i].iter().collect();
                if chars.len() > i + 1 {
                    let variant: String = chars[i + 1..].iter().collect();
                    return locale_to_string(&lang, &country, &variant);
                } else {
                    return locale_to_string(&lang, &country, "");
                }
            }
            sep_found = true;
        }
    }
    if !sep_found {
        locale_to_string(s, "", "")
    } else {
        let country: String = chars[position..].iter().collect();
        locale_to_string(&lang, &country, "")
    }
}

// ---------------------------------------------------------------------------
// java.util.HashMap iteration order (for request parameter maps)

fn java_string_hash(s: &str) -> i32 {
    let mut h: i32 = 0;
    for u in s.encode_utf16() {
        h = h.wrapping_mul(31).wrapping_add(u as i32);
    }
    h
}

fn spread(h: i32) -> u32 {
    let h = h as u32;
    h ^ (h >> 16)
}

/// Minimal emulation of `java.util.HashMap<String, _>` key ordering.
pub struct JavaHashMap<V> {
    table: Vec<Vec<(String, u32, V)>>,
    threshold: usize,
    size: usize,
}

impl<V> JavaHashMap<V> {
    pub fn new() -> Self {
        JavaHashMap { table: Vec::new(), threshold: 0, size: 0 }
    }
    pub fn with_capacity(initial: usize) -> Self {
        let mut n: usize = 1;
        while n < initial {
            n <<= 1;
        }
        JavaHashMap { table: Vec::new(), threshold: n, size: 0 }
    }
    fn resize(&mut self) {
        let old_cap = self.table.len();
        let old_thr = self.threshold;
        let (new_cap, mut new_thr);
        if old_cap > 0 {
            new_cap = old_cap << 1;
            new_thr = if old_cap >= 16 { old_thr << 1 } else { 0 };
        } else if old_thr > 0 {
            new_cap = old_thr;
            new_thr = 0;
        } else {
            new_cap = 16;
            new_thr = 12;
        }
        if new_thr == 0 {
            new_thr = ((new_cap as f32) * 0.75f32) as usize;
        }
        self.threshold = new_thr;
        let old = std::mem::take(&mut self.table);
        self.table = (0..new_cap).map(|_| Vec::new()).collect();
        for bucket in old {
            for (k, h, v) in bucket {
                let idx = (h as usize) & (new_cap - 1);
                self.table[idx].push((k, h, v));
            }
        }
    }
    pub fn get_mut(&mut self, key: &str) -> Option<&mut V> {
        if self.table.is_empty() {
            return None;
        }
        let h = spread(java_string_hash(key));
        let idx = (h as usize) & (self.table.len() - 1);
        self.table[idx].iter_mut().find(|e| e.0 == key).map(|e| &mut e.2)
    }
    pub fn put(&mut self, key: String, v: V) {
        if let Some(slot) = self.get_mut(&key) {
            *slot = v;
            return;
        }
        if self.table.is_empty() {
            self.resize();
        }
        let h = spread(java_string_hash(&key));
        let idx = (h as usize) & (self.table.len() - 1);
        self.table[idx].push((key, h, v));
        self.size += 1;
        if self.size > self.threshold {
            self.resize();
        }
    }
    pub fn len(&self) -> usize {
        self.size
    }
    pub fn into_entries(self) -> Vec<(String, V)> {
        self.table.into_iter().flatten().map(|(k, _, v)| (k, v)).collect()
    }
}

/// Request parameters in the order Spring sees them (Jetty MultiMap ->
/// HashMap -> LinkedMultiValueMap).
pub fn spring_param_order(params: Vec<(String, String)>) -> Vec<(String, Vec<String>)> {
    let mut mm: JavaHashMap<Vec<String>> = JavaHashMap::new();
    for (k, v) in params {
        if let Some(list) = mm.get_mut(&k) {
            list.push(v);
        } else {
            mm.put(k, vec![v]);
        }
    }
    let size = mm.len();
    let entries = mm.into_entries();
    let mut hm: JavaHashMap<Vec<String>> = JavaHashMap::with_capacity(size * 3 / 2);
    for (k, v) in entries {
        hm.put(k, v);
    }
    hm.into_entries()
}

/// Java `String.split("\\s*,\\s*")` (trailing empty strings removed).
pub fn split_comma(s: &str) -> Vec<String> {
    // find separators: maximal runs of whitespace around a comma
    let chars: Vec<char> = s.chars().collect();
    let is_ws = |c: char| matches!(c, ' ' | '\t' | '\n' | '\u{000B}' | '\u{000C}' | '\r');
    let mut parts = Vec::new();
    let mut start = 0usize;
    let mut i = 0usize;
    let mut found = false;
    while i < chars.len() {
        // try to match \s*,\s* starting at i
        let mut j = i;
        while j < chars.len() && is_ws(chars[j]) {
            j += 1;
        }
        if j < chars.len() && chars[j] == ',' {
            let mut k = j + 1;
            while k < chars.len() && is_ws(chars[k]) {
                k += 1;
            }
            // Java: a zero-length leading match never happens here (comma required)
            if !(i == 0 && k == 0) {
                parts.push(chars[start..i].iter().collect::<String>());
                found = true;
            }
            start = k;
            i = k;
            continue;
        }
        i += 1;
    }
    if !found {
        return vec![s.to_string()];
    }
    parts.push(chars[start..].iter().collect::<String>());
    while parts.len() > 0 && parts.last().map(|p| p.is_empty()).unwrap_or(false) {
        parts.pop();
    }
    parts
}

/// Java serialization of `java.lang.Double` (what Hibernate writes into a
/// bytea column for a serializable value).
pub fn java_serialized_double(v: f64) -> Vec<u8> {
    let mut out: Vec<u8> = vec![
        0xAC, 0xED, 0x00, 0x05, 0x73, 0x72, 0x00, 0x10,
    ];
    out.extend_from_slice(b"java.lang.Double");
    out.extend_from_slice(&[0x80, 0xB3, 0xC2, 0x4A, 0x29, 0x6B, 0xFB, 0x04, 0x02, 0x00, 0x01, 0x44, 0x00, 0x05]);
    out.extend_from_slice(b"value");
    out.extend_from_slice(&[0x78, 0x72, 0x00, 0x10]);
    out.extend_from_slice(b"java.lang.Number");
    out.extend_from_slice(&[0x86, 0xAC, 0x95, 0x1D, 0x0B, 0x94, 0xE0, 0x8B, 0x02, 0x00, 0x00, 0x78, 0x70]);
    out.extend_from_slice(&v.to_bits().to_be_bytes());
    out
}

/// Reads back a Java-serialized `Double` (the value is the trailing 8 bytes).
pub fn java_deserialize_double(b: &[u8]) -> Option<f64> {
    if b.len() < 8 {
        return None;
    }
    let mut a = [0u8; 8];
    a.copy_from_slice(&b[b.len() - 8..]);
    Some(f64::from_bits(u64::from_be_bytes(a)))
}

