/// Declared (static) type of an association, which decides how JSON is read.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Decl {
    /// abstract `LayerDataSource`: Jackson cannot build it
    Lds,
    TileGrid,
    WmtsTileGrid,
    Extent,
    Appearance,
    User,
    Role,
}

impl Decl {
    pub fn class(self) -> Option<Class> {
        match self {
            Decl::Lds => None,
            Decl::TileGrid => Some(Class::TileGrid),
            Decl::WmtsTileGrid => Some(Class::WmtsTileGrid),
            Decl::Extent => Some(Class::Extent),
            Decl::Appearance => Some(Class::LayerAppearance),
            Decl::User => Some(Class::User),
            Decl::Role => Some(Class::Role),
        }
    }
}

/// Hibernate entity "family" (root entity) – ids are unique per family in a
/// session.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Family {
    Role,
    Person,
    UserGroup,
    Layer,
    LayerAppearance,
    Extent,
    TileGrid,
    Lds,
}

#[derive(Clone, Copy, Debug)]
pub enum Kind {
    Str(&'static str),
    /// column, primitive (int)
    Int(&'static str, bool),
    /// column, primitive (boolean)
    Bool(&'static str, bool),
