    Locale(&'static str),
    Point(&'static str, &'static str),
    ToOne { col: &'static str, decl: Decl, cascade: bool },
    /// ManyToMany set of entities (roles, members): join table, owner column, element column
    EntSet { table: &'static str, owner: &'static str, elem: &'static str, decl: Decl },
    /// `User.userGroups`: serialized as ids, read through the id resolver
    GroupRefs { table: &'static str, owner: &'static str, elem: &'static str },
    /// element collection of strings without index
