//! JSON -> entity mapping with the coercion rules of the original's Jackson
//! (2.14, default features) setup.

use crate::javaish::{double_to_string, java_parse_double, java_parse_int, java_parse_long};
use crate::model::{Class, Decl, Kind, Obj, PropVal, V};
use chrono::{Datelike, NaiveDate};
use serde_json::{Map, Number, Value};

pub type JResult<T> = Result<T, String>;

/// Collected while reading: ids of user groups referenced through
/// `User.userGroups` (they are resolved – and permission checked – by the
/// original's id resolver while reading).
#[derive(Default, Debug)]
pub struct ReadCtx {
    pub group_refs: Vec<i32>,
}

/// Parses the request body like Jackson does: the first JSON value, trailing
/// content is ignored. `Ok(None)` for empty content.
pub fn parse_body(text: &str) -> Result<Option<Value>, String> {
    if text.trim_matches(|c: char| c == ' ' || c == '\t' || c == '\n' || c == '\r').is_empty() {
        return Ok(None);
    }
    let mut it = serde_json::Deserializer::from_str(text).into_iter::<Value>();
    match it.next() {
        Some(Ok(v)) => Ok(Some(v)),
        Some(Err(e)) => Err(e.to_string()),
        None => Ok(None),
    }
}

fn is_int_token(n: &Number) -> bool {
    let s = n.to_string();
    !s.contains(['.', 'e', 'E'])
}

fn num_text_java(n: &Number) -> String {
    // text Jackson would produce for a number when converted to String
    n.to_string()
}

pub fn coerce_str(v: &Value) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        Value::String(s) => Ok(V::Str(s.clone())),
        Value::Number(n) => Ok(V::Str(num_text_java(n))),
        Value::Bool(b) => Ok(V::Str(b.to_string())),
        _ => Err("cannot deserialize String".into()),
    }
}

fn is_textual_null(s: &str) -> bool {
    s == "null"
}

pub fn coerce_int(v: &Value, prim: bool) -> JResult<V> {
    let null = if prim { V::Int(0) } else { V::Null };
    match v {
        Value::Null => Ok(null),
        Value::Number(n) => {
            if is_int_token(n) {
                let s = n.to_string();
                match java_parse_long(&s) {
                    Some(l) if l >= i32::MIN as i64 && l <= i32::MAX as i64 => Ok(V::Int(l as i32)),
                    _ => Err("int out of range".into()),
                }
            } else {
                let d = n.as_f64().ok_or("bad number")?;
                if d.is_nan() || d < i32::MIN as f64 || d > i32::MAX as f64 {
                    return Err("int out of range".into());
                }
                Ok(V::Int(d.trunc() as i32))
            }
        }
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() || is_textual_null(t) {
                return Ok(null);
            }
            if t.len() > 9 {
                match java_parse_long(t) {
                    Some(l) if l >= i32::MIN as i64 && l <= i32::MAX as i64 => Ok(V::Int(l as i32)),
                    _ => Err("not an int".into()),
                }
            } else {
                java_parse_int(t).map(V::Int).ok_or_else(|| "not an int".to_string())
            }
        }
        _ => Err("cannot deserialize int".into()),
    }
}

pub fn coerce_bool(v: &Value, prim: bool) -> JResult<V> {
    let null = if prim { V::Bool(false) } else { V::Null };
    match v {
        Value::Null => Ok(null),
        Value::Bool(b) => Ok(V::Bool(*b)),
        Value::Number(n) if is_int_token(n) => {
            let s = n.to_string();
            let zero = s.trim_start_matches('-').chars().all(|c| c == '0');
            Ok(V::Bool(!zero))
        }
        Value::String(s) => {
            let t = s.trim();
            match t {
                "true" | "True" | "TRUE" => Ok(V::Bool(true)),
                "false" | "False" | "FALSE" => Ok(V::Bool(false)),
                "" | "null" => Ok(null),
                _ => Err("not a boolean".into()),
            }
        }
        _ => Err("cannot deserialize boolean".into()),
    }
}

fn special_double(t: &str) -> Option<f64> {
    match t {
        "NaN" => Some(f64::NAN),
        "Infinity" | "+Infinity" | "INF" | "+INF" => Some(f64::INFINITY),
        "-Infinity" | "-INF" => Some(f64::NEG_INFINITY),
        _ => None,
    }
}

pub fn coerce_double(v: &Value, prim: bool) -> JResult<V> {
    let null = if prim { V::Dbl(0.0) } else { V::Null };
    match v {
        Value::Null => Ok(null),
        Value::Number(n) => Ok(V::Dbl(n.as_f64().ok_or("bad number")?)),
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() || is_textual_null(t) {
                return Ok(null);
            }
            if let Some(d) = special_double(t) {
                return Ok(V::Dbl(d));
            }
            java_parse_double(t).map(V::Dbl).ok_or_else(|| "not a double".to_string())
        }
        _ => Err("cannot deserialize double".into()),
    }
}

fn parse_local_date(t: &str) -> Option<NaiveDate> {
    // Joda ISODateTimeFormat.localDateParser(): yyyy[-MM[-dd]] | yyyy-DDD
    let (sign, body) = match t.as_bytes().first()? {
        b'-' => (-1, &t[1..]),
        b'+' => (1, &t[1..]),
        _ => (1, t),
    };
    let parts: Vec<&str> = body.split('-').collect();
    let num = |s: &str, min: usize, max: usize| -> Option<i32> {
        if s.len() < min || s.len() > max || !s.bytes().all(|c| c.is_ascii_digit()) {
            return None;
        }
        s.parse().ok()
    };
    let year = sign * num(parts[0], 1, 9)?;
    match parts.len() {
        1 => NaiveDate::from_ymd_opt(year, 1, 1),
        2 => {
            if parts[1].len() == 3 {
                let doy = num(parts[1], 3, 3)?;
                NaiveDate::from_yo_opt(year, doy as u32)
            } else {
                let m = num(parts[1], 1, 2)?;
                NaiveDate::from_ymd_opt(year, m as u32, 1)
            }
        }
        3 => {
            let m = num(parts[1], 1, 2)?;
            let d = num(parts[2], 1, 2)?;
            NaiveDate::from_ymd_opt(year, m as u32, d as u32)
        }
        _ => None,
    }
}

pub fn coerce_date(v: &Value) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                return Ok(V::Null);
            }
            parse_local_date(t).map(V::Date).ok_or_else(|| "bad date".to_string())
        }
        Value::Array(a) => {
            if a.len() != 3 {
                return Err("bad date array".into());
            }
            let mut n = [0i64; 3];
            for (i, x) in a.iter().enumerate() {
                match x {
                    Value::Number(num) if is_int_token(num) => n[i] = num.as_i64().ok_or("bad")?,
                    _ => return Err("bad date array".into()),
                }
            }
            NaiveDate::from_ymd_opt(n[0] as i32, n[1] as u32, n[2] as u32)
                .map(V::Date)
                .ok_or_else(|| "bad date".to_string())
        }
        Value::Number(n) if is_int_token(n) => {
            let ms = n.as_i64().ok_or("bad")?;
            let dt = chrono::DateTime::from_timestamp_millis(ms).ok_or("bad")?;
            let d = dt.date_naive();
            Ok(V::Date(NaiveDate::from_ymd_opt(d.year(), d.month(), d.day()).unwrap()))
        }
        _ => Err("cannot deserialize LocalDate".into()),
    }
}

pub fn coerce_locale(v: &Value) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        Value::String(s) => Ok(V::Locale(crate::javaish::locale_from_jackson(s))),
        Value::Number(n) => Ok(V::Locale(crate::javaish::locale_from_jackson(&n.to_string()))),
        Value::Bool(b) => Ok(V::Locale(crate::javaish::locale_from_jackson(&b.to_string()))),
        _ => Err("cannot deserialize Locale".into()),
    }
}

fn coerce_point(v: &Value) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        Value::Object(m) => {
            let (mut x, mut y) = (0.0, 0.0);
            for (k, val) in m {
                let d = match coerce_double(val, true)? {
                    V::Dbl(d) => d,
                    _ => 0.0,
                };
                match k.as_str() {
                    "x" => x = d,
                    "y" => y = d,
                    _ => return Err(format!("unknown property {} of Point2D", k)),
                }
            }
            Ok(V::Point(x, y))
        }
        _ => Err("cannot deserialize Point2D".into()),
    }
}

/// Java `toString()` of a value Jackson produced for a `Map<String,Object>`.
pub fn java_to_string(v: &Value) -> String {
    match v {
        Value::Null => "null".into(),
        Value::Bool(b) => b.to_string(),
        Value::String(s) => s.clone(),
        Value::Number(n) => {
            if is_int_token(n) {
                let s = n.to_string();
                // BigInteger/Long/Integer toString: strip sign of zero, leading zeros impossible in JSON
                if s == "-0" {
                    "0".into()
                } else {
                    s
                }
            } else {
                double_to_string(n.as_f64().unwrap_or(0.0))
            }
        }
        Value::Array(a) => {
            let parts: Vec<String> = a.iter().map(java_to_string).collect();
            format!("[{}]", parts.join(", "))
        }
        Value::Object(m) => {
            let parts: Vec<String> = m.iter().map(|(k, v)| format!("{}={}", k, java_to_string(v))).collect();
            format!("{{{}}}", parts.join(", "))
        }
    }
}

/// Value as Jackson would serialize it again (doubles normalised).
fn untyped_json(v: &Value) -> Value {
    match v {
        Value::Number(n) if !is_int_token(n) => {
            let d = n.as_f64().unwrap_or(0.0);
            Number::from_f64(d).map(Value::Number).unwrap_or(Value::Null)
        }
        Value::Array(a) => Value::Array(a.iter().map(untyped_json).collect()),
        Value::Object(m) => Value::Object(m.iter().map(|(k, v)| (k.clone(), untyped_json(v))).collect()),
        other => other.clone(),
    }
}

fn read_props(v: &Value) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        Value::Object(m) => {
            let mut out: Vec<(String, PropVal)> = vec![];
            for (k, val) in m {
                let pv = PropVal {
                    json: untyped_json(val),
                    text: if val.is_null() { None } else { Some(java_to_string(val)) },
                };
                if let Some(e) = out.iter_mut().find(|e| &e.0 == k) {
                    e.1 = pv;
                } else {
                    out.push((k.clone(), pv));
                }
            }
            Ok(V::Props(out))
        }
        _ => Err("cannot deserialize Map".into()),
    }
}

fn read_list<F: Fn(&Value) -> JResult<V>>(v: &Value, elem: F) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        Value::Array(a) => {
            let mut out = vec![];
            for e in a {
                out.push(elem(e)?);
            }
            Ok(V::List(out))
        }
        _ => Err("cannot deserialize collection".into()),
    }
}

fn dedupe_set(v: V) -> V {
    match v {
        V::List(items) => {
            let mut out: Vec<V> = vec![];
            for i in items {
                if !out.contains(&i) {
                    out.push(i);
                }
            }
            V::List(out)
        }
        other => other,
    }
}

/// Reads an entity of the given declared type (`null` -> `V::Null`).
pub fn read_decl(decl: Decl, v: &Value, ctx: &mut ReadCtx) -> JResult<V> {
    if v.is_null() {
        return Ok(V::Null);
    }
    let class = match decl.class() {
        Some(c) => c,
        None => return Err("abstract type LayerDataSource cannot be constructed".into()),
    };
    match v {
        Value::Object(m) => {
            let mut o = Obj::new(class);
            apply_object(&mut o, m, ctx)?;
            Ok(V::Obj(Box::new(o)))
        }
        _ => Err(format!("cannot deserialize {:?} from non-object", class)),
    }
}

fn read_group_ref(v: &Value, ctx: &mut ReadCtx) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        _ => match coerce_int(v, false)? {
            V::Int(i) => {
                ctx.group_refs.push(i);
                Ok(V::Ref(i))
            }
            _ => Ok(V::Null),
        },
    }
}

/// Reads the value of one property.
pub fn read_field(kind: &Kind, v: &Value, ctx: &mut ReadCtx) -> JResult<V> {
    match *kind {
        Kind::Str(_) => coerce_str(v),
        Kind::Int(_, prim) => coerce_int(v, prim),
        Kind::Bool(_, prim) => coerce_bool(v, prim),
        Kind::Dbl(_) => coerce_double(v, false),
        Kind::Date(_) => coerce_date(v),
        Kind::Locale(_) => coerce_locale(v),
        Kind::Point(_, _) => coerce_point(v),
        Kind::ToOne { decl, .. } => read_decl(decl, v, ctx),
        Kind::EntSet { decl, .. } => {
            let l = match v {
                Value::Null => V::Null,
                Value::Array(a) => {
                    let mut out = vec![];
                    for e in a {
                        out.push(read_decl(decl, e, ctx)?);
                    }
                    V::List(out)
                }
                _ => return Err("cannot deserialize Set".into()),
            };
            Ok(dedupe_set(l))
        }
        Kind::GroupRefs { .. } => {
            let l = match v {
                Value::Null => V::Null,
                Value::Array(a) => {
                    let mut out = vec![];
                    for e in a {
                        out.push(read_group_ref(e, ctx)?);
                    }
                    V::List(out)
                }
                _ => return Err("cannot deserialize Set".into()),
            };
            Ok(dedupe_set(l))
        }
        Kind::StrBag { .. } => read_list(v, coerce_str),
        Kind::DblList { .. } | Kind::XyzRes => read_list(v, |e| coerce_double(e, false)),
        Kind::Props => read_props(v),
    }
}

/// Applies the properties of a JSON object onto an entity (Jackson's
/// `readerForUpdating` semantics: top level properties are replaced,
/// nested values are freshly constructed).
pub fn apply_object(o: &mut Obj, m: &Map<String, Value>, ctx: &mut ReadCtx) -> JResult<()> {
    for (k, v) in m {
        if k == "id" {
            o.id = match coerce_int(v, false)? {
                V::Int(i) => Some(i),
                _ => None,
            };
            continue;
        }
        if Class::is_ignored_property(k) {
            continue;
        }
        let fd = o
            .class
            .field(k)
            .ok_or_else(|| format!("Unrecognized field \"{}\" for {:?}", k, o.class))?;
        let val = read_field(&fd.kind, v, ctx)?;
        o.f.insert(fd.name, val);
    }
    Ok(())
}

/// Jackson `JsonNode.asInt()`.
pub fn json_as_int(v: &Value) -> i32 {
    match v {
        Value::Number(n) => {
            if is_int_token(n) {
                // long -> int narrowing
                let s = n.to_string();
                if let Some(l) = java_parse_long(&s) {
                    l as i32
                } else {
                    // BigInteger.intValue(): low 32 bits
                    let neg = s.starts_with('-');
                    let digits = s.trim_start_matches('-');
                    let mut acc: u32 = 0;
                    for c in digits.bytes() {
                        acc = acc.wrapping_mul(10).wrapping_add((c - b'0') as u32);
                    }
                    let r = acc as i32;
                    if neg {
                        r.wrapping_neg()
                    } else {
                        r
                    }
                }
            } else {
                let d = n.as_f64().unwrap_or(0.0);
                java_d2i(d)
            }
        }
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                return 0;
            }
            if let Some(i) = java_parse_int(t) {
                return i;
            }
            match java_parse_double(t) {
                Some(d) => java_d2i(d),
                None => 0,
            }
        }
        Value::Bool(b) => *b as i32,
        _ => 0,
    }
}

fn java_d2i(d: f64) -> i32 {
    if d.is_nan() {
        0
    } else if d >= i32::MAX as f64 {
        i32::MAX
    } else if d <= i32::MIN as f64 {
        i32::MIN
    } else {
        d as i32
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn string_coercion() {
        assert_eq!(coerce_str(&json!(5)).unwrap(), V::Str("5".into()));
        assert_eq!(coerce_str(&json!(true)).unwrap(), V::Str("true".into()));
        assert!(coerce_str(&json!({"a":1})).is_err());
        assert!(coerce_str(&json!(["a"])).is_err());
    }

    #[test]
    fn number_coercion() {
        assert_eq!(coerce_int(&json!("12"), false).unwrap(), V::Int(12));
        assert_eq!(coerce_int(&json!(""), false).unwrap(), V::Null);
        assert_eq!(coerce_int(&json!(null), true).unwrap(), V::Int(0));
        assert_eq!(coerce_int(&json!(1.9), true).unwrap(), V::Int(1));
        assert!(coerce_int(&json!(true), false).is_err());
        assert!(coerce_int(&json!(10000000000i64), false).is_err());
        assert_eq!(coerce_double(&json!("0.5"), false).unwrap(), V::Dbl(0.5));
        assert!(coerce_double(&json!("abc"), false).is_err());
        assert_eq!(coerce_bool(&json!(1), false).unwrap(), V::Bool(true));
        assert_eq!(coerce_bool(&json!("True"), false).unwrap(), V::Bool(true));
        assert!(coerce_bool(&json!("yes"), false).is_err());
    }

    #[test]
    fn dates() {
        assert_eq!(coerce_date(&json!("2001-1-5")).unwrap(), V::Date(NaiveDate::from_ymd_opt(2001, 1, 5).unwrap()));
        assert_eq!(coerce_date(&json!([2001, 1, 5])).unwrap(), V::Date(NaiveDate::from_ymd_opt(2001, 1, 5).unwrap()));
        assert_eq!(coerce_date(&json!(978307200000i64)).unwrap(), V::Date(NaiveDate::from_ymd_opt(2001, 1, 1).unwrap()));
        assert!(coerce_date(&json!("2001-01-05T10:00:00")).is_err());
    }

    #[test]
    fn to_string_like_java() {
        let v: Value = serde_json::from_str(r#"{"a":[1,2],"b":{"x":1},"d":1e20,"f":0.1}"#).unwrap();
        assert_eq!(java_to_string(&v["a"]), "[1, 2]");
        assert_eq!(java_to_string(&v["b"]), "{x=1}");
        assert_eq!(java_to_string(&v["d"]), "1.0E20");
        assert_eq!(java_to_string(&v["f"]), "0.1");
    }

    #[test]
    fn unknown_property_fails() {
        let mut o = Obj::new(Class::Role);
        let m = json!({"nme": "x"});
        assert!(apply_object(&mut o, m.as_object().unwrap(), &mut ReadCtx::default()).is_err());
        let m = json!({"name": "x", "created": 5, "userPermissions": {}});
        assert!(apply_object(&mut o, m.as_object().unwrap(), &mut ReadCtx::default()).is_ok());
    }

    #[test]
    fn abstract_source_is_refused() {
        let mut o = Obj::new(Class::Layer);
        let m = json!({"source": {"id": 3}});
        assert!(apply_object(&mut o, m.as_object().unwrap(), &mut ReadCtx::default()).is_err());
        let m = json!({"source": null});
        assert!(apply_object(&mut o, m.as_object().unwrap(), &mut ReadCtx::default()).is_ok());
    }

    #[test]
    fn as_int() {
        assert_eq!(json_as_int(&json!("42")), 42);
        assert_eq!(json_as_int(&json!(42.7)), 42);
        assert_eq!(json_as_int(&json!(true)), 1);
        assert_eq!(json_as_int(&json!(null)), 0);
        assert_eq!(json_as_int(&json!("abc")), 0);
    }
}

tool_use_result.content:
//! JSON -> entity mapping with the coercion rules of the original's Jackson
//! (2.14, default features) setup.

use crate::javaish::{double_to_string, java_parse_double, java_parse_int, java_parse_long};
use crate::model::{Class, Decl, Kind, Obj, PropVal, V};
use chrono::{Datelike, NaiveDate};
use serde_json::{Map, Number, Value};

pub type JResult<T> = Result<T, String>;

/// Collected while reading: ids of user groups referenced through
/// `User.userGroups` (they are resolved – and permission checked – by the
/// original's id resolver while reading).
#[derive(Default, Debug)]
pub struct ReadCtx {
    pub group_refs: Vec<i32>,
}

/// Parses the request body like Jackson does: the first JSON value, trailing
/// content is ignored. `Ok(None)` for empty content.
pub fn parse_body(text: &str) -> Result<Option<Value>, String> {
    if text.trim_matches(|c: char| c == ' ' || c == '\t' || c == '\n' || c == '\r').is_empty() {
        return Ok(None);
    }
    let mut it = serde_json::Deserializer::from_str(text).into_iter::<Value>();
    match it.next() {
        Some(Ok(v)) => Ok(Some(v)),
        Some(Err(e)) => Err(e.to_string()),
        None => Ok(None),
    }
}

fn is_int_token(n: &Number) -> bool {
    let s = n.to_string();
    !s.contains(['.', 'e', 'E'])
}

fn num_text_java(n: &Number) -> String {
    // text Jackson would produce for a number when converted to String
    n.to_string()
}

pub fn coerce_str(v: &Value) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        Value::String(s) => Ok(V::Str(s.clone())),
        Value::Number(n) => Ok(V::Str(num_text_java(n))),
        Value::Bool(b) => Ok(V::Str(b.to_string())),
        _ => Err("cannot deserialize String".into()),
    }
}

fn is_textual_null(s: &str) -> bool {
    s == "null"
}

pub fn coerce_int(v: &Value, prim: bool) -> JResult<V> {
    let null = if prim { V::Int(0) } else { V::Null };
    match v {
        Value::Null => Ok(null),
        Value::Number(n) => {
            if is_int_token(n) {
                let s = n.to_string();
                match java_parse_long(&s) {
                    Some(l) if l >= i32::MIN as i64 && l <= i32::MAX as i64 => Ok(V::Int(l as i32)),
                    _ => Err("int out of range".into()),
                }
            } else {
                let d = n.as_f64().ok_or("bad number")?;
                if d.is_nan() || d < i32::MIN as f64 || d > i32::MAX as f64 {
                    return Err("int out of range".into());
                }
                Ok(V::Int(d.trunc() as i32))
            }
        }
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() || is_textual_null(t) {
                return Ok(null);
            }
            if t.len() > 9 {
                match java_parse_long(t) {
                    Some(l) if l >= i32::MIN as i64 && l <= i32::MAX as i64 => Ok(V::Int(l as i32)),
                    _ => Err("not an int".into()),
                }
            } else {
                java_parse_int(t).map(V::Int).ok_or_else(|| "not an int".to_string())
            }
        }
        _ => Err("cannot deserialize int".into()),
    }
}

pub fn coerce_bool(v: &Value, prim: bool) -> JResult<V> {
    let null = if prim { V::Bool(false) } else { V::Null };
    match v {
        Value::Null => Ok(null),
        Value::Bool(b) => Ok(V::Bool(*b)),
        Value::Number(n) if is_int_token(n) => {
            let s = n.to_string();
            let zero = s.trim_start_matches('-').chars().all(|c| c == '0');
            Ok(V::Bool(!zero))
        }
        Value::String(s) => {
            let t = s.trim();
            match t {
                "true" | "True" | "TRUE" => Ok(V::Bool(true)),
                "false" | "False" | "FALSE" => Ok(V::Bool(false)),
                "" | "null" => Ok(null),
                _ => Err("not a boolean".into()),
            }
        }
        _ => Err("cannot deserialize boolean".into()),
    }
}

fn special_double(t: &str) -> Option<f64> {
    match t {
        "NaN" => Some(f64::NAN),
        "Infinity" | "+Infinity" | "INF" | "+INF" => Some(f64::INFINITY),
        "-Infinity" | "-INF" => Some(f64::NEG_INFINITY),
        _ => None,
    }
}

pub fn coerce_double(v: &Value, prim: bool) -> JResult<V> {
    let null = if prim { V::Dbl(0.0) } else { V::Null };
    match v {
        Value::Null => Ok(null),
        Value::Number(n) => Ok(V::Dbl(n.as_f64().ok_or("bad number")?)),
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() || is_textual_null(t) {
                return Ok(null);
            }
            if let Some(d) = special_double(t) {
                return Ok(V::Dbl(d));
            }
            java_parse_double(t).map(V::Dbl).ok_or_else(|| "not a double".to_string())
        }
        _ => Err("cannot deserialize double".into()),
    }
}

fn parse_local_date(t: &str) -> Option<NaiveDate> {
    // Joda ISODateTimeFormat.localDateParser(): yyyy[-MM[-dd]] | yyyy-DDD
    let (sign, body) = match t.as_bytes().first()? {
        b'-' => (-1, &t[1..]),
        b'+' => (1, &t[1..]),
        _ => (1, t),
    };
    let parts: Vec<&str> = body.split('-').collect();
    let num = |s: &str, min: usize, max: usize| -> Option<i32> {
        if s.len() < min || s.len() > max || !s.bytes().all(|c| c.is_ascii_digit()) {
            return None;
        }
        s.parse().ok()
    };
    let year = sign * num(parts[0], 1, 9)?;
    match parts.len() {
        1 => NaiveDate::from_ymd_opt(year, 1, 1),
        2 => {
            if parts[1].len() == 3 {
                let doy = num(parts[1], 3, 3)?;
                NaiveDate::from_yo_opt(year, doy as u32)
            } else {
                let m = num(parts[1], 1, 2)?;
                NaiveDate::from_ymd_opt(year, m as u32, 1)
            }
        }
        3 => {
            let m = num(parts[1], 1, 2)?;
            let d = num(parts[2], 1, 2)?;
            NaiveDate::from_ymd_opt(year, m as u32, d as u32)
        }
        _ => None,
    }
}

pub fn coerce_date(v: &Value) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                return Ok(V::Null);
            }
            parse_local_date(t).map(V::Date).ok_or_else(|| "bad date".to_string())
        }
        Value::Array(a) => {
            if a.len() != 3 {
                return Err("bad date array".into());
            }
            let mut n = [0i64; 3];
            for (i, x) in a.iter().enumerate() {
                match x {
                    Value::Number(num) if is_int_token(num) => n[i] = num.as_i64().ok_or("bad")?,
                    _ => return Err("bad date array".into()),
                }
            }
            NaiveDate::from_ymd_opt(n[0] as i32, n[1] as u32, n[2] as u32)
                .map(V::Date)
                .ok_or_else(|| "bad date".to_string())
        }
        Value::Number(n) if is_int_token(n) => {
            let ms = n.as_i64().ok_or("bad")?;
            let dt = chrono::DateTime::from_timestamp_millis(ms).ok_or("bad")?;
            let d = dt.date_naive();
            Ok(V::Date(NaiveDate::from_ymd_opt(d.year(), d.month(), d.day()).unwrap()))
        }
        _ => Err("cannot deserialize LocalDate".into()),
    }
}

pub fn coerce_locale(v: &Value) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        Value::String(s) => Ok(V::Locale(crate::javaish::locale_from_jackson(s))),
        Value::Number(n) => Ok(V::Locale(crate::javaish::locale_from_jackson(&n.to_string()))),
        Value::Bool(b) => Ok(V::Locale(crate::javaish::locale_from_jackson(&b.to_string()))),
        _ => Err("cannot deserialize Locale".into()),
    }
}

fn coerce_point(v: &Value) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        Value::Object(m) => {
            let (mut x, mut y) = (0.0, 0.0);
            for (k, val) in m {
                let d = match coerce_double(val, true)? {
                    V::Dbl(d) => d,
                    _ => 0.0,
                };
                match k.as_str() {
                    "x" => x = d,
                    "y" => y = d,
                    _ => return Err(format!("unknown property {} of Point2D", k)),
                }
            }
            Ok(V::Point(x, y))
        }
        _ => Err("cannot deserialize Point2D".into()),
    }
}

/// Java `toString()` of a value Jackson produced for a `Map<String,Object>`.
pub fn java_to_string(v: &Value) -> String {
    match v {
        Value::Null => "null".into(),
        Value::Bool(b) => b.to_string(),
        Value::String(s) => s.clone(),
        Value::Number(n) => {
            if is_int_token(n) {
                let s = n.to_string();
                // BigInteger/Long/Integer toString: strip sign of zero, leading zeros impossible in JSON
                if s == "-0" {
                    "0".into()
                } else {
                    s
                }
            } else {
                double_to_string(n.as_f64().unwrap_or(0.0))
            }
        }
        Value::Array(a) => {
            let parts: Vec<String> = a.iter().map(java_to_string).collect();
            format!("[{}]", parts.join(", "))
        }
        Value::Object(m) => {
            let parts: Vec<String> = m.iter().map(|(k, v)| format!("{}={}", k, java_to_string(v))).collect();
            format!("{{{}}}", parts.join(", "))
        }
    }
}

/// Value as Jackson would serialize it again (doubles normalised).
fn untyped_json(v: &Value) -> Value {
    match v {
        Value::Number(n) if !is_int_token(n) => {
            let d = n.as_f64().unwrap_or(0.0);
            Number::from_f64(d).map(Value::Number).unwrap_or(Value::Null)
        }
        Value::Array(a) => Value::Array(a.iter().map(untyped_json).collect()),
        Value::Object(m) => Value::Object(m.iter().map(|(k, v)| (k.clone(), untyped_json(v))).collect()),
        other => other.clone(),
    }
}

fn read_props(v: &Value) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        Value::Object(m) => {
            let mut out: Vec<(String, PropVal)> = vec![];
            for (k, val) in m {
                let pv = PropVal {
                    json: untyped_json(val),
                    text: if val.is_null() { None } else { Some(java_to_string(val)) },
                };
                if let Some(e) = out.iter_mut().find(|e| &e.0 == k) {
                    e.1 = pv;
                } else {
                    out.push((k.clone(), pv));
                }
            }
            Ok(V::Props(out))
        }
        _ => Err("cannot deserialize Map".into()),
    }
}

fn read_list<F: Fn(&Value) -> JResult<V>>(v: &Value, elem: F) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        Value::Array(a) => {
            let mut out = vec![];
            for e in a {
                out.push(elem(e)?);
            }
            Ok(V::List(out))
        }
        _ => Err("cannot deserialize collection".into()),
    }
}

fn dedupe_set(v: V) -> V {
    match v {
        V::List(items) => {
            let mut out: Vec<V> = vec![];
            for i in items {
                if !out.contains(&i) {
                    out.push(i);
                }
            }
            V::List(out)
        }
        other => other,
    }
}

/// Reads an entity of the given declared type (`null` -> `V::Null`).
pub fn read_decl(decl: Decl, v: &Value, ctx: &mut ReadCtx) -> JResult<V> {
    if v.is_null() {
        return Ok(V::Null);
    }
    let class = match decl.class() {
        Some(c) => c,
        None => return Err("abstract type LayerDataSource cannot be constructed".into()),
    };
    match v {
        Value::Object(m) => {
            let mut o = Obj::new(class);
            apply_object(&mut o, m, ctx)?;
            Ok(V::Obj(Box::new(o)))
        }
        _ => Err(format!("cannot deserialize {:?} from non-object", class)),
    }
}

fn read_group_ref(v: &Value, ctx: &mut ReadCtx) -> JResult<V> {
    match v {
        Value::Null => Ok(V::Null),
        _ => match coerce_int(v, false)? {
            V::Int(i) => {
                ctx.group_refs.push(i);
                Ok(V::Ref(i))
            }
            _ => Ok(V::Null),
        },
    }
}

/// Reads the value of one property.
pub fn read_field(kind: &Kind, v: &Value, ctx: &mut ReadCtx) -> JResult<V> {
    match *kind {
        Kind::Str(_) => coerce_str(v),
        Kind::Int(_, prim) => coerce_int(v, prim),
        Kind::Bool(_, prim) => coerce_bool(v, prim),
        Kind::Dbl(_) => coerce_double(v, false),
        Kind::Date(_) => coerce_date(v),
        Kind::Locale(_) => coerce_locale(v),
        Kind::Point(_, _) => coerce_point(v),
        Kind::ToOne { decl, .. } => read_decl(decl, v, ctx),
        Kind::EntSet { decl, .. } => {
            let l = match v {
                Value::Null => V::Null,
                Value::Array(a) => {
                    let mut out = vec![];
                    for e in a {
                        out.push(read_decl(decl, e, ctx)?);
                    }
                    V::List(out)
                }
                _ => return Err("cannot deserialize Set".into()),
            };
            Ok(dedupe_set(l))
        }
        Kind::GroupRefs { .. } => {
            let l = match v {
                Value::Null => V::Null,
                Value::Array(a) => {
                    let mut out = vec![];
                    for e in a {
                        out.push(read_group_ref(e, ctx)?);
                    }
                    V::List(out)
                }
                _ => return Err("cannot deserialize Set".into()),
            };
            Ok(dedupe_set(l))
        }
        Kind::StrBag { .. } => read_list(v, coerce_str),
        Kind::DblList { .. } | Kind::XyzRes => read_list(v, |e| coerce_double(e, false)),
        Kind::Props => read_props(v),
    }
}

/// Applies the properties of a JSON object onto an entity (Jackson's
/// `readerForUpdating` semantics: top level properties are replaced,
/// nested values are freshly constructed).
pub fn apply_object(o: &mut Obj, m: &Map<String, Value>, ctx: &mut ReadCtx) -> JResult<()> {
    for (k, v) in m {
        if k == "id" {
            o.id = match coerce_int(v, false)? {
                V::Int(i) => Some(i),
                _ => None,
            };
            continue;
        }
        if Class::is_ignored_property(k) {
            continue;
        }
        let fd = o
            .class
            .field(k)
            .ok_or_else(|| format!("Unrecognized field \"{}\" for {:?}", k, o.class))?;
        let val = read_field(&fd.kind, v, ctx)?;
        o.f.insert(fd.name, val);
    }
    Ok(())
}

/// Jackson `JsonNode.asInt()`.
pub fn json_as_int(v: &Value) -> i32 {
    match v {
        Value::Number(n) => {
            if is_int_token(n) {
                // long -> int narrowing
                let s = n.to_string();
                if let Some(l) = java_parse_long(&s) {
                    l as i32
                } else {
                    // BigInteger.intValue(): low 32 bits
                    let neg = s.starts_with('-');
                    let digits = s.trim_start_matches('-');
                    let mut acc: u32 = 0;
                    for c in digits.bytes() {
                        acc = acc.wrapping_mul(10).wrapping_add((c - b'0') as u32);
                    }
                    let r = acc as i32;
                    if neg {
                        r.wrapping_neg()
                    } else {
                        r
                    }
                }
            } else {
                let d = n.as_f64().unwrap_or(0.0);
                java_d2i(d)
            }
        }
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                return 0;
            }
            if let Some(i) = java_parse_int(t) {
                return i;
            }
            match java_parse_double(t) {
                Some(d) => java_d2i(d),
                None => 0,
            }
        }
        Value::Bool(b) => *b as i32,
        _ => 0,
    }
}

fn java_d2i(d: f64) -> i32 {
    if d.is_nan() {
        0
    } else if d >= i32::MAX as f64 {
        i32::MAX
    } else if d <= i32::MIN as f64 {
        i32::MIN
    } else {
        d as i32
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn string_coercion() {
        assert_eq!(coerce_str(&json!(5)).unwrap(), V::Str("5".into()));
        assert_eq!(coerce_str(&json!(true)).unwrap(), V::Str("true".into()));
        assert!(coerce_str(&json!({"a":1})).is_err());
        assert!(coerce_str(&json!(["a"])).is_err());
    }

    #[test]
    fn number_coercion() {
        assert_eq!(coerce_int(&json!("12"), false).unwrap(), V::Int(12));
        assert_eq!(coerce_int(&json!(""), false).unwrap(), V::Null);
        assert_eq!(coerce_int(&json!(null), true).unwrap(), V::Int(0));
        assert_eq!(coerce_int(&json!(1.9), true).unwrap(), V::Int(1));
        assert!(coerce_int(&json!(true), false).is_err());
        assert!(coerce_int(&json!(10000000000i64), false).is_err());
        assert_eq!(coerce_double(&json!("0.5"), false).unwrap(), V::Dbl(0.5));
        assert!(coerce_double(&json!("abc"), false).is_err());
        assert_eq!(coerce_bool(&json!(1), false).unwrap(), V::Bool(true));
        assert_eq!(coerce_bool(&json!("True"), false).unwrap(), V::Bool(true));
        assert!(coerce_bool(&json!("yes"), false).is_err());
    }

    #[test]
    fn dates() {
        assert_eq!(coerce_date(&json!("2001-1-5")).unwrap(), V::Date(NaiveDate::from_ymd_opt(2001, 1, 5).unwrap()));
        assert_eq!(coerce_date(&json!([2001, 1, 5])).unwrap(), V::Date(NaiveDate::from_ymd_opt(2001, 1, 5).unwrap()));
        assert_eq!(coerce_date(&json!(978307200000i64)).unwrap(), V::Date(NaiveDate::from_ymd_opt(2001, 1, 1).unwrap()));
        assert!(coerce_date(&json!("2001-01-05T10:00:00")).is_err());
    }

    #[test]
    fn to_string_like_java() {
        let v: Value = serde_json::from_str(r#"{"a":[1,2],"b":{"x":1},"d":1e20,"f":0.1}"#).unwrap();
        assert_eq!(java_to_string(&v["a"]), "[1, 2]");
        assert_eq!(java_to_string(&v["b"]), "{x=1}");
        assert_eq!(java_to_string(&v["d"]), "1.0E20");
        assert_eq!(java_to_string(&v["f"]), "0.1");
    }

    #[test]
    fn unknown_property_fails() {
        let mut o = Obj::new(Class::Role);
        let m = json!({"nme": "x"});
        assert!(apply_object(&mut o, m.as_object().unwrap(), &mut ReadCtx::default()).is_err());
        let m = json!({"name": "x", "created": 5, "userPermissions": {}});
        assert!(apply_object(&mut o, m.as_object().unwrap(), &mut ReadCtx::default()).is_ok());
    }

    #[test]
    fn abstract_source_is_refused() {
        let mut o = Obj::new(Class::Layer);
        let m = json!({"source": {"id": 3}});
        assert!(apply_object(&mut o, m.as_object().unwrap(), &mut ReadCtx::default()).is_err());
        let m = json!({"source": null});
        assert!(apply_object(&mut o, m.as_object().unwrap(), &mut ReadCtx::default()).is_ok());
    }

    #[test]
    fn as_int() {
        assert_eq!(json_as_int(&json!("42")), 42);
        assert_eq!(json_as_int(&json!(42.7)), 42);
        assert_eq!(json_as_int(&json!(true)), 1);
        assert_eq!(json_as_int(&json!(null)), 0);
        assert_eq!(json_as_int(&json!("abc")), 0);
    }
}

