//! Database access: loading entity graphs, writing them back the way
//! Hibernate does, deleting, and the list / filter queries.

use crate::javaish::{is_digits, is_parsable, java_deserialize_double, java_parse_double, java_parse_long, locale_from_db};
use crate::model::{Class, Decl, Family, Kind, Obj, PropVal, SimpleType, V};
use chrono::NaiveDateTime;
use serde_json::{Number, Value};
use std::collections::{HashMap, HashSet};
use std::future::Future;
use std::pin::Pin;
use tokio_postgres::types::ToSql;
use tokio_postgres::{GenericClient, Row};

pub type DbResult<T> = Result<T, String>;
type BoxFut<'a, T> = Pin<Box<dyn Future<Output = T> + Send + 'a>>;

fn e2s(e: tokio_postgres::Error) -> String {
    match e.as_db_error() {
        Some(d) => format!("{}: {}", d.code().code(), d.message()),
        None => e.to_string(),
    }
}

// ---------------------------------------------------------------------------
// loading

/// Loads entity graphs; keeps every entity it touched (like a Hibernate
/// session) so the same row is only read once per request.
pub struct Loader<'c, C: GenericClient + Sync> {
    pub client: &'c C,
    cache: HashMap<(Family, i32), Option<Obj>>,
}

fn select_columns(class: Class) -> (String, Vec<&'static crate::model::Field>) {
    let mut cols = vec![];
    let mut fields = vec![];
    for f in class.fields() {
        match f.kind {
            Kind::Str(c) | Kind::Int(c, _) | Kind::Bool(c, _) | Kind::Dbl(c) | Kind::Date(c) | Kind::Locale(c) => {
                cols.push(format!("{}.{}", f.table, c));
                fields.push(f);
            }
            Kind::Point(x, y) => {
                cols.push(format!("{}.{}", f.table, x));
                cols.push(format!("{}.{}", f.table, y));
                fields.push(f);
            }
            Kind::ToOne { col, .. } => {
                cols.push(format!("{}.{}", f.table, col));
                fields.push(f);
            }
            _ => {}
        }
    }
    (cols.join(", "), fields)
}

pub fn from_clause(class: Class) -> String {
    let tables = class.tables();
    let mut s = tables[0].to_string();
    for t in &tables[1..] {
        s.push_str(&format!(" JOIN {} ON {}.id = {}.id", t, t, tables[0]));
    }
    s
}

/// Converts a stored property value like the original's `PropertyValueConverter`.
pub fn prop_from_db(text: &str) -> DbResult<Value> {
    if text.eq_ignore_ascii_case("true") {
        return Ok(Value::Bool(true));
    }
    if text.eq_ignore_ascii_case("false") {
        return Ok(Value::Bool(false));
    }
    if is_parsable(text) {
        let digits = is_digits(text) || (text.starts_with('-') && is_digits(&text[1..]));
        if digits {
            let l = java_parse_long(text).ok_or("NumberFormatException")?;
            return Ok(Value::Number(l.into()));
        }
        let d = java_parse_double(text).ok_or("NumberFormatException")?;
        return Ok(Number::from_f64(d).map(Value::Number).unwrap_or(Value::Null));
    }
    Ok(Value::String(text.to_string()))
}

impl<'c, C: GenericClient + Sync> Loader<'c, C> {
    pub fn new(client: &'c C) -> Self {
        Loader { client, cache: HashMap::new() }
    }

    /// (family, id) of every entity read so far.
    pub fn loaded(&self) -> HashSet<(Family, i32)> {
        self.cache.iter().filter(|(_, v)| v.is_some()).map(|(k, _)| *k).collect()
    }

    pub async fn lds_class(&self, id: i32) -> DbResult<Option<Class>> {
        let row = self
            .client
            .query_opt(
                "SELECT (SELECT count(*) FROM tilewmslayerdatasources t WHERE t.id = l.id), \
                        (SELECT count(*) FROM imagewmslayerdatasources t WHERE t.id = l.id), \
                        (SELECT count(*) FROM wfslayerdatasources t WHERE t.id = l.id), \
                        (SELECT count(*) FROM wmtslayerdatasources t WHERE t.id = l.id), \
                        (SELECT count(*) FROM xyzlayerdatasources t WHERE t.id = l.id) \
                 FROM layerdatasources l WHERE l.id = $1",
                &[&id],
            )
            .await
            .map_err(e2s)?;
        let row = match row {
            None => return Ok(None),
            Some(r) => r,
        };
        let c: Vec<i64> = (0..5).map(|i| row.get::<_, i64>(i)).collect();
        Ok(if c[0] > 0 {
            Some(Class::TileWms)
        } else if c[1] > 0 {
            Some(Class::ImageWms)
        } else if c[2] > 0 {
            Some(Class::Wfs)
        } else if c[3] > 0 {
            Some(Class::Wmts)
        } else if c[4] > 0 {
            Some(Class::Xyz)
        } else {
            return Err("cannot instantiate abstract class LayerDataSource".into());
        })
    }

    pub async fn tilegrid_class(&self, id: i32) -> DbResult<Option<Class>> {
        let row = self
            .client
            .query_opt(
                "SELECT (SELECT count(*) FROM wmtstilegrids w WHERE w.id = t.id) FROM tilegrids t WHERE t.id = $1",
                &[&id],
            )
            .await
            .map_err(e2s)?;
        Ok(row.map(|r| if r.get::<_, i64>(0) > 0 { Class::WmtsTileGrid } else { Class::TileGrid }))
    }

    /// Loads the entity with the given id as the declared type (polymorphic
    /// for data sources and tile grids).
    pub fn load_decl<'a>(&'a mut self, decl: Decl, id: i32) -> BoxFut<'a, DbResult<Option<Obj>>> {
        Box::pin(async move {
            let class = match decl {
                Decl::Lds => match self.lds_class(id).await? {
                    Some(c) => c,
                    None => return Ok(None),
                },
                Decl::TileGrid | Decl::WmtsTileGrid => match self.tilegrid_class(id).await? {
                    Some(c) => {
                        if decl == Decl::WmtsTileGrid && c != Class::WmtsTileGrid {
                            return Err("wrong tile grid type".into());
                        }
                        c
                    }
                    None => return Ok(None),
                },
                other => other.class().unwrap(),
            };
            self.load(class, id).await
        })
    }

    /// Loads an entity of exactly this class (for data sources use
    /// `load_decl`).
    pub fn load<'a>(&'a mut self, class: Class, id: i32) -> BoxFut<'a, DbResult<Option<Obj>>> {
        Box::pin(async move {
            let key = (class.family(), id);
            if let Some(c) = self.cache.get(&key) {
                if let Some(o) = c {
                    if o.class == class {
                        return Ok(Some(o.clone()));
                    }
                    return Ok(None);
                }
                return Ok(None);
            }
            let (cols, fields) = select_columns(class);
            let tables = class.tables();
            let sql = format!(
                "SELECT {}.id{}{} FROM {} WHERE {}.id = $1",
                tables[0],
                if cols.is_empty() { "" } else { ", " },
                cols,
                from_clause(class),
                tables[0]
            );
            let row = self.client.query_opt(sql.as_str(), &[&id]).await.map_err(e2s)?;
            let row = match row {
                None => {
                    self.cache.insert(key, None);
                    return Ok(None);
                }
                Some(r) => r,
            };
            let mut o = Obj::new(class);
            o.id = Some(id);
            self.fill_scalars(&mut o, &row, 1, &fields).await?;
            // collections
            for f in class.fields() {
                let v = self.load_collection(&f.kind, id).await?;
                if let Some(v) = v {
                    o.f.insert(f.name, v);
                }
            }
            self.cache.insert(key, Some(o.clone()));
            Ok(Some(o))
        })
    }

    async fn fill_scalars(
        &mut self,
        o: &mut Obj,
        row: &Row,
        start: usize,
        fields: &[&'static crate::model::Field],
    ) -> DbResult<()> {
        let mut i = start;
        for f in fields {
            let v = match f.kind {
                Kind::Str(_) => {
                    let s: Option<String> = row.get(i);
                    i += 1;
                    s.map(V::Str).unwrap_or(V::Null)
                }
                Kind::Int(_, prim) => {
                    let s: Option<i32> = row.get(i);
                    i += 1;
                    match s {
                        Some(x) => V::Int(x),
                        None if prim => V::Int(0),
                        None => V::Null,
                    }
                }
                Kind::Bool(_, prim) => {
                    let s: Option<bool> = row.get(i);
                    i += 1;
                    match s {
                        Some(x) => V::Bool(x),
                        None if prim => V::Bool(false),
                        None => V::Null,
                    }
                }
                Kind::Dbl(_) => {
                    let s: Option<f64> = row.get(i);
                    i += 1;
                    s.map(V::Dbl).unwrap_or(V::Null)
                }
                Kind::Date(_) => {
                    let s: Option<chrono::NaiveDate> = row.get(i);
                    i += 1;
                    s.map(V::Date).unwrap_or(V::Null)
                }
                Kind::Locale(_) => {
                    let s: Option<String> = row.get(i);
                    i += 1;
                    s.map(|s| V::Locale(locale_from_db(&s))).unwrap_or(V::Null)
                }
                Kind::Point(_, _) => {
                    let x: Option<f64> = row.get(i);
                    let y: Option<f64> = row.get(i + 1);
                    i += 2;
                    if x.is_none() && y.is_none() {
                        V::Null
                    } else {
                        V::Point(x.unwrap_or(0.0), y.unwrap_or(0.0))
                    }
                }
                Kind::ToOne { decl, .. } => {
                    let r: Option<i32> = row.get(i);
                    i += 1;
                    match r {
                        None => V::Null,
                        Some(rid) => match self.load_decl(decl, rid).await? {
                            Some(t) => V::Obj(Box::new(t)),
                            None => V::Null,
                        },
                    }
                }
                _ => continue,
            };
            o.f.insert(f.name, v);
        }
        Ok(())
    }

    async fn load_collection(&mut self, kind: &Kind, id: i32) -> DbResult<Option<V>> {
        let c = self.client;
        Ok(Some(match *kind {
            Kind::EntSet { table, owner, elem, decl } => {
                let rows = c
                    .query(format!("SELECT {} FROM {} WHERE {} = $1", elem, table, owner).as_str(), &[&id])
                    .await
                    .map_err(e2s)?;
                let mut out = vec![];
                for r in rows {
                    let eid: i32 = r.get(0);
                    if let Some(o) = self.load_decl(decl, eid).await? {
                        out.push(V::Obj(Box::new(o)));
                    }
                }
                V::List(out)
            }
            Kind::GroupRefs { table, owner, elem } => {
                let rows = c
                    .query(
                        format!("SELECT j.{} FROM {} j JOIN usergroups g ON g.id = j.{} WHERE j.{} = $1", elem, table, elem, owner)
                            .as_str(),
                        &[&id],
                    )
                    .await
                    .map_err(e2s)?;
                V::List(rows.iter().map(|r| V::Ref(r.get(0))).collect())
            }
            Kind::StrBag { table, owner, col } => {
                let rows = c
                    .query(format!("SELECT {} FROM {} WHERE {} = $1", col, table, owner).as_str(), &[&id])
                    .await
                    .map_err(e2s)?;
                V::List(
                    rows.iter()
                        .filter_map(|r| r.get::<_, Option<String>>(0))
                        .map(V::Str)
                        .collect(),
                )
            }
            Kind::DblList { table, owner, col, idx } => {
                let rows = c
                    .query(
                        format!("SELECT {}, {} FROM {} WHERE {} = $1 ORDER BY {}", col, idx, table, owner, idx).as_str(),
                        &[&id],
                    )
                    .await
                    .map_err(e2s)?;
                let mut list: Vec<V> = vec![];
                for r in rows {
                    let v: Option<f64> = r.get(0);
                    let i: i32 = r.get(1);
                    if i < 0 {
                        continue;
                    }
                    let i = i as usize;
                    while list.len() <= i {
                        list.push(V::Null);
                    }
                    list[i] = v.map(V::Dbl).unwrap_or(V::Null);
                }
                V::List(list)
            }
            Kind::XyzRes => {
                let rows = c
                    .query(
                        "SELECT resolution, idx FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1 ORDER BY idx",
                        &[&id],
                    )
                    .await
                    .map_err(e2s)?;
                let mut list: Vec<V> = vec![];
                for r in rows {
                    let v: Option<Vec<u8>> = r.get(0);
                    let i: i32 = r.get(1);
                    if i < 0 {
                        continue;
                    }
                    let i = i as usize;
                    while list.len() <= i {
                        list.push(V::Null);
                    }
                    list[i] = v.and_then(|b| java_deserialize_double(&b)).map(V::Dbl).unwrap_or(V::Null);
                }
                V::List(list)
            }
            Kind::Props => {
                let rows = c
                    .query("SELECT property, value FROM layerappearances_properties WHERE appearance_id = $1", &[&id])
                    .await
                    .map_err(e2s)?;
                let mut out = vec![];
                for r in rows {
                    let k: String = r.get(0);
                    let v: Option<String> = r.get(1);
                    if let Some(t) = v {
                        out.push((k, PropVal { json: prop_from_db(&t)?, text: Some(t) }));
                    }
                }
                V::Props(out)
            }
            _ => return Ok(None),
        }))
    }

    /// Loads a root entity of a resource (polymorphic for data sources).
    pub async fn load_resource(&mut self, class: Class, id: i32) -> DbResult<Option<Obj>> {
        match class.family() {
            Family::Lds => self.load_decl(Decl::Lds, id).await,
            _ => self.load(class, id).await,
        }
    }
}

// ---------------------------------------------------------------------------
// queries for list / filter endpoints

pub enum Param {
    Str(String),
    Int(i32),
    Bool(bool),
    Dbl(f64),
}

impl Param {
    fn as_sql(&self) -> &(dyn ToSql + Sync) {
        match self {
            Param::Str(s) => s,
            Param::Int(i) => i,
            Param::Bool(b) => b,
            Param::Dbl(d) => d,
        }
    }
}

/// A filter: AND over properties, OR over the values of each property.
/// Each entry: (qualified column, values).
pub type Filter = Vec<(String, Vec<Param>)>;

fn where_clause(filter: &Filter, params: &mut Vec<&(dyn ToSql + Sync)>) -> String {
    let mut ands = vec![];
    for (col, vals) in filter {
        let mut ors = vec![];
        for v in vals {
            params.push(v.as_sql());
            ors.push(format!("{} = ${}", col, params.len()));
        }
        ands.push(format!("({})", ors.join(" OR ")));
    }
    if ands.is_empty() {
        String::new()
    } else {
        format!(" WHERE {}", ands.join(" AND "))
    }
}

/// The table/alias whose rows are the resource's entities.
pub fn resource_from(class: Class) -> (String, &'static str) {
    match class.family() {
        Family::Lds => ("layerdatasources".into(), "layerdatasources"),
        Family::Person => ("users JOIN persons ON persons.id = users.id".into(), "persons"),
        _ => {
            let t = class.tables()[0];
            (t.into(), t)
        }
    }
}

pub fn lds_from() -> String {
    "layerdatasources \
     LEFT JOIN imagewmslayerdatasources ON imagewmslayerdatasources.id = layerdatasources.id \
     LEFT JOIN tilewmslayerdatasources ON tilewmslayerdatasources.id = layerdatasources.id \
     LEFT JOIN wfslayerdatasources ON wfslayerdatasources.id = layerdatasources.id \
     LEFT JOIN wmtslayerdatasources ON wmtslayerdatasources.id = layerdatasources.id \
     LEFT JOIN xyzlayerdatasources ON xyzlayerdatasources.id = layerdatasources.id"
        .into()
}

pub async fn query_ids<C: GenericClient + Sync>(c: &C, class: Class, filter: &Filter) -> DbResult<Vec<i32>> {
    let (from, root) = resource_from(class);
    let from = if class.family() == Family::Lds { lds_from() } else { from };
    let mut params: Vec<&(dyn ToSql + Sync)> = vec![];
    let w = where_clause(filter, &mut params);
    let sql = format!("SELECT DISTINCT {}.id FROM {}{}", root, from, w);
    let rows = c.query(sql.as_str(), &params).await.map_err(e2s)?;
    Ok(rows.iter().map(|r| r.get(0)).collect())
}

/// Projection query for `output:only`: returns beans with only the given
/// properties set (the rest keeps the constructor defaults).
pub async fn query_restricted<C: GenericClient + Sync>(
    c: &C,
    class: Class,
    props: &[(&'static str, SimpleType, String)],
    filter: &Filter,
) -> DbResult<Vec<Obj>> {
    let (from, _) = resource_from(class);
    let from = if class.family() == Family::Lds { lds_from() } else { from };
    let mut params: Vec<&(dyn ToSql + Sync)> = vec![];
    let w = where_clause(filter, &mut params);
    let cols: Vec<String> = props.iter().map(|p| p.2.clone()).collect();
    let sql = format!("SELECT {} FROM {}{}", cols.join(", "), from, w);
    let rows = c.query(sql.as_str(), &params).await.map_err(e2s)?;
    let mut out = vec![];
    for r in rows {
        let mut o = Obj::new(class);
        for (i, (name, ty, _)) in props.iter().enumerate() {
            let v = match ty {
                SimpleType::Str => r.get::<_, Option<String>>(i).map(V::Str).unwrap_or(V::Null),
                SimpleType::Int => r.get::<_, Option<i32>>(i).map(V::Int).unwrap_or(V::Null),
                SimpleType::Bool => r.get::<_, Option<bool>>(i).map(V::Bool).unwrap_or(V::Null),
                SimpleType::Dbl => r.get::<_, Option<f64>>(i).map(V::Dbl).unwrap_or(V::Null),
            };
            if *name == "id" {
                o.id = match v {
                    V::Int(i) => Some(i),
                    _ => None,
                };
            } else {
                // primitives keep their default when the column is NULL
                let v = if v == V::Null { class.default_value(name) } else { v };
                o.f.insert(name, v);
            }
        }
        out.push(o);
    }
    Ok(out)
}

// ---------------------------------------------------------------------------
// id generation

/// Hibernate table generator on `hibernate_sequences` (row `default`): runs
/// in its own transaction, so an allocated id stays consumed.
pub async fn next_id<C: GenericClient + Sync>(c: &C) -> DbResult<i32> {
    let row = c
        .query_opt(
            "UPDATE hibernate_sequences SET next_val = next_val + 1 WHERE sequence_name = 'default' RETURNING next_val",
            &[],
        )
        .await
        .map_err(e2s)?;
    if let Some(r) = row {
        let v: Option<i64> = r.get(0);
        return v.map(|v| v as i32).ok_or_else(|| "next_val is null".to_string());
    }
    let row = c
        .query_one(
            "INSERT INTO hibernate_sequences(sequence_name, next_val) VALUES ('default', 1) \
             ON CONFLICT (sequence_name) DO UPDATE SET next_val = hibernate_sequences.next_val + 1 RETURNING next_val",
            &[],
        )
        .await
        .map_err(e2s)?;
    let v: Option<i64> = row.get(0);
    v.map(|v| v as i32).ok_or_else(|| "next_val is null".to_string())
}

// ---------------------------------------------------------------------------
// saving

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SaveMode {
    /// new entity: INSERT
    Insert,
    /// detached entity reattached by cascade: full UPDATE incl. collections
    Reattach,
    /// persistent (loaded) root: UPDATE, only the given collections rewritten
    Persistent,
}

/// One entity write, in execution order.
struct Write {
    obj: Obj,
    mode: SaveMode,
    /// for Persistent: names of collection properties to rewrite
    touched: Option<HashSet<&'static str>>,
}

/// Prepares the writes of a save (root + cascades) like Hibernate's
/// saveOrUpdate + flush: allocates ids in pre-order (through `idc`, outside
/// the main transaction) and detects session conflicts.
pub struct SavePlan {
    writes: Vec<Write>,
}

pub struct Planner<'a, C: GenericClient + Sync> {
    idc: &'a C,
    session: HashSet<(Family, i32)>,
}

impl<'a, C: GenericClient + Sync> Planner<'a, C> {
    pub fn new(idc: &'a C, session: HashSet<(Family, i32)>) -> Self {
        Planner { idc, session }
    }

    /// Plans the save of `root`. For `Persistent`, only the properties in
    /// `touched` were changed by the request. Ids allocated so far stay
    /// consumed when an error is returned.
    pub async fn plan(&mut self, root: &mut Obj, mode: SaveMode, touched: Option<HashSet<&'static str>>) -> DbResult<SavePlan> {
        let mut writes = vec![];
        if mode == SaveMode::Insert {
            let id = next_id(self.idc).await?;
            root.id = Some(id);
            self.session.insert((root.class.family(), id));
        }
        self.cascade(root, touched.as_ref(), &mut writes).await?;
        // transient references (non-cascaded associations without id)
        check_transient(root, touched.as_ref())?;
        for w in &writes {
            check_transient(&w.obj, None)?;
        }
        writes.push(Write { obj: root.clone(), mode, touched });
        Ok(SavePlan { writes })
    }

    fn cascade<'b>(
        &'b mut self,
        o: &'b mut Obj,
        only: Option<&'b HashSet<&'static str>>,
        writes: &'b mut Vec<Write>,
    ) -> BoxFut<'b, DbResult<()>> {
        Box::pin(async move {
            let class = o.class;
            for f in class.fields() {
                if let Some(only) = only {
                    if !only.contains(f.name) {
                        continue;
                    }
                }
                if let Kind::ToOne { cascade: true, .. } = f.kind {
                    if let Some(V::Obj(child)) = o.f.get_mut(f.name) {
                        let fam = child.class.family();
                        let mode = match child.id {
                            None => {
                                let id = next_id(self.idc).await?;
                                child.id = Some(id);
                                self.session.insert((fam, id));
                                SaveMode::Insert
                            }
                            Some(id) => {
                                if self.session.contains(&(fam, id)) {
                                    return Err(format!(
                                        "NonUniqueObjectException: a different object with the identifier value [{}] was already associated with the session",
                                        id
                                    ));
                                }
                                self.session.insert((fam, id));
                                SaveMode::Reattach
                            }
                        };
                        self.cascade(child, None, writes).await?;
                        writes.push(Write { obj: (**child).clone(), mode, touched: None });
                    }
                }
            }
            Ok(())
        })
    }
}

fn check_transient(o: &Obj, only: Option<&HashSet<&'static str>>) -> DbResult<()> {
    for f in o.class.fields() {
        if let Some(only) = only {
            if !only.contains(f.name) {
                continue;
            }
        }
        match f.kind {
            Kind::ToOne { cascade: false, .. } => {
                if let V::Obj(c) = o.get(f.name) {
                    if c.id.is_none() {
                        return Err("TransientObjectException".into());
                    }
                }
            }
            Kind::EntSet { .. } => {
                if let V::List(items) = o.get(f.name) {
                    for i in items {
                        if let V::Obj(c) = i {
                            if c.id.is_none() {
                                return Err("TransientObjectException".into());
                            }
                        }
                    }
                }
            }
            _ => {}
        }
    }
    Ok(())
}

fn column_values(o: &Obj, table: &str) -> (Vec<String>, Vec<Box<dyn ToSql + Sync + Send>>) {
    let mut cols = vec![];
    let mut vals: Vec<Box<dyn ToSql + Sync + Send>> = vec![];
    for f in o.class.fields() {
        if f.table != table {
            continue;
        }
        let v = o.get(f.name);
        match f.kind {
            Kind::Str(c) => {
                cols.push(c.to_string());
                vals.push(Box::new(match v {
                    V::Str(s) => Some(s.clone()),
                    _ => None,
                }));
            }
            Kind::Locale(c) => {
                cols.push(c.to_string());
                vals.push(Box::new(match v {
                    V::Locale(s) => Some(s.clone()),
                    _ => None,
                }));
            }
            Kind::Int(c, _) => {
                cols.push(c.to_string());
                vals.push(Box::new(match v {
                    V::Int(i) => Some(*i),
                    _ => None,
                }));
            }
            Kind::Bool(c, _) => {
                cols.push(c.to_string());
                vals.push(Box::new(match v {
                    V::Bool(b) => Some(*b),
                    _ => None,
                }));
            }
            Kind::Dbl(c) => {
                cols.push(c.to_string());
                vals.push(Box::new(match v {
                    V::Dbl(d) => Some(*d),
                    _ => None,
                }));
            }
            Kind::Date(c) => {
                cols.push(c.to_string());
                vals.push(Box::new(match v {
                    V::Date(d) => Some(*d),
                    _ => None,
                }));
            }
            Kind::Point(x, y) => {
                cols.push(x.to_string());
                cols.push(y.to_string());
                let (px, py) = match v {
                    V::Point(a, b) => (Some(*a), Some(*b)),
                    _ => (None, None),
                };
                vals.push(Box::new(px));
                vals.push(Box::new(py));
            }
            Kind::ToOne { col, .. } => {
                cols.push(col.to_string());
                vals.push(Box::new(match v {
                    V::Obj(c) => c.id,
                    _ => None,
                }));
            }
            _ => {}
        }
    }
    (cols, vals)
}

async fn exec<C: GenericClient + Sync>(c: &C, sql: &str, vals: &[Box<dyn ToSql + Sync + Send>]) -> DbResult<u64> {
    let refs: Vec<&(dyn ToSql + Sync)> = vals.iter().map(|b| b.as_ref() as &(dyn ToSql + Sync)).collect();
    c.execute(sql, &refs).await.map_err(e2s)
}

async fn write_entity<C: GenericClient + Sync>(c: &C, w: &Write, now: NaiveDateTime) -> DbResult<()> {
    let o = &w.obj;
    let id = o.id.ok_or("entity without id")?;
    let tables = o.class.tables();
    for (ti, table) in tables.iter().enumerate() {
        let (mut cols, mut vals) = column_values(o, table);
        match w.mode {
            SaveMode::Insert => {
                if ti == 0 {
                    cols.push("created".into());
                    vals.push(Box::new(now));
                    cols.push("modified".into());
                    vals.push(Box::new(now));
                }
                cols.push("id".into());
                vals.push(Box::new(id));
                let ph: Vec<String> = (1..=vals.len()).map(|i| format!("${}", i)).collect();
                let sql = format!("INSERT INTO {} ({}) VALUES ({})", table, cols.join(", "), ph.join(", "));
                exec(c, &sql, &vals).await?;
            }
            SaveMode::Reattach | SaveMode::Persistent => {
                if ti == 0 {
                    cols.push("modified".into());
                    vals.push(Box::new(now));
                }
                if cols.is_empty() {
                    // table without own columns: Hibernate does not touch it,
                    // but the row must exist for the entity type
                    let n = c
                        .execute(format!("SELECT 1 FROM {} WHERE id = $1", table).as_str(), &[&id])
                        .await
                        .map_err(e2s)?;
                    if n != 1 {
                        return Err("StaleStateException".into());
                    }
                    continue;
                }
                let sets: Vec<String> = cols.iter().enumerate().map(|(i, c)| format!("{} = ${}", c, i + 1)).collect();
                vals.push(Box::new(id));
                let sql = format!("UPDATE {} SET {} WHERE id = ${}", table, sets.join(", "), vals.len());
                let n = exec(c, &sql, &vals).await?;
                if n != 1 {
                    return Err("StaleStateException: unexpected row count".into());
                }
            }
        }
    }
    // collections
    for f in o.class.fields() {
        let rewrite = match w.mode {
            SaveMode::Insert => false,
            SaveMode::Reattach => true,
            SaveMode::Persistent => w.touched.as_ref().map(|t| t.contains(f.name)).unwrap_or(false),
        };
        let (table, owner) = match collection_table(&f.kind) {
            Some(x) => x,
            None => continue,
        };
        if rewrite {
            c.execute(format!("DELETE FROM {} WHERE {} = $1", table, owner).as_str(), &[&id])
                .await
                .map_err(e2s)?;
        }
        if w.mode == SaveMode::Insert || rewrite {
            insert_collection(c, &f.kind, id, o.get(f.name)).await?;
        }
    }
    Ok(())
}

fn collection_table(k: &Kind) -> Option<(&'static str, &'static str)> {
    match *k {
        Kind::EntSet { table, owner, .. } => Some((table, owner)),
        Kind::GroupRefs { table, owner, .. } => Some((table, owner)),
        Kind::StrBag { table, owner, .. } => Some((table, owner)),
        Kind::DblList { table, owner, .. } => Some((table, owner)),
        Kind::XyzRes => Some(("xyzlayerdatasrc_resolution", "xyzlayerdatasrc_id")),
        Kind::Props => Some(("layerappearances_properties", "appearance_id")),
        _ => None,
    }
}

async fn insert_collection<C: GenericClient + Sync>(c: &C, k: &Kind, id: i32, v: &V) -> DbResult<()> {
    match (k, v) {
        (Kind::EntSet { table, owner, elem, .. }, V::List(items)) => {
            for i in items {
                if let V::Obj(o) = i {
                    let eid = o.id.ok_or("TransientObjectException")?;
                    c.execute(
                        format!("INSERT INTO {} ({}, {}) VALUES ($1, $2)", table, owner, elem).as_str(),
                        &[&id, &eid],
                    )
                    .await
                    .map_err(e2s)?;
                }
            }
        }
        (Kind::GroupRefs { table, owner, elem }, V::List(items)) => {
            for i in items {
                if let V::Ref(gid) = i {
                    c.execute(
                        format!("INSERT INTO {} ({}, {}) VALUES ($1, $2)", table, owner, elem).as_str(),
                        &[&id, gid],
                    )
                    .await
                    .map_err(e2s)?;
                }
            }
        }
        (Kind::StrBag { table, owner, col }, V::List(items)) => {
            for i in items {
                if let V::Str(s) = i {
                    c.execute(
                        format!("INSERT INTO {} ({}, {}) VALUES ($1, $2)", table, owner, col).as_str(),
                        &[&id, s],
                    )
                    .await
                    .map_err(e2s)?;
                }
            }
        }
        (Kind::DblList { table, owner, col, idx }, V::List(items)) => {
            for (n, i) in items.iter().enumerate() {
                if let V::Dbl(d) = i {
                    let n = n as i32;
                    c.execute(
                        format!("INSERT INTO {} ({}, {}, {}) VALUES ($1, $2, $3)", table, owner, col, idx).as_str(),
                        &[&id, d, &n],
                    )
                    .await
                    .map_err(e2s)?;
                }
            }
        }
        (Kind::XyzRes, V::List(items)) => {
            if items.iter().any(|i| *i != V::Null) {
                // the original cannot write these values into its bytea column
                return Err("could not write XYZ resolutions".into());
            }
        }
        (Kind::Props, V::Props(items)) => {
            for (key, pv) in items {
                if let Some(t) = &pv.text {
                    c.execute(
                        "INSERT INTO layerappearances_properties (appearance_id, value, property) VALUES ($1, $2, $3)",
                        &[&id, t, key],
                    )
                    .await
                    .map_err(e2s)?;
                }
            }
        }
        _ => {}
    }
    Ok(())
}

impl SavePlan {
    pub async fn execute<C: GenericClient + Sync>(&self, c: &C, now: NaiveDateTime) -> DbResult<()> {
        for w in &self.writes {
            write_entity(c, w, now).await?;
        }
        Ok(())
    }
}

// ---------------------------------------------------------------------------
// deleting

/// Deletes an entity (and what Hibernate cascades a delete to).
pub fn delete_entity<'a, C: GenericClient + Sync>(c: &'a C, o: &'a Obj) -> BoxFut<'a, DbResult<()>> {
    Box::pin(async move {
        let id = o.id.ok_or("no id")?;
        // collection rows first
        c.execute("DELETE FROM userpermissions WHERE entity_id = $1", &[&id]).await.map_err(e2s)?;
        c.execute("DELETE FROM grouppermissions WHERE entity_id = $1", &[&id]).await.map_err(e2s)?;
        for f in o.class.fields() {
            if let Some((table, owner)) = collection_table(&f.kind) {
                c.execute(format!("DELETE FROM {} WHERE {} = $1", table, owner).as_str(), &[&id])
                    .await
                    .map_err(e2s)?;
            }
        }
        // tables from leaf to root
        for t in o.class.tables().iter().rev() {
            c.execute(format!("DELETE FROM {} WHERE id = $1", t).as_str(), &[&id]).await.map_err(e2s)?;
        }
        // CascadeType.ALL associations (WMTS tile grid)
        if o.class == Class::Wmts {
            if let V::Obj(tg) = o.get("tileGrid") {
                delete_entity(c, tg).await?;
            }
        }
        Ok(())
    })
}

/// `LayerService.delete`: removes the layer from all maps first.
pub async fn maps_with_layer<C: GenericClient + Sync>(c: &C, layer_id: i32) -> DbResult<Vec<i32>> {
    let rows = c
        .query("SELECT DISTINCT map_id FROM maps_layers WHERE layer_id = $1", &[&layer_id])
        .await
        .map_err(e2s)?;
    Ok(rows.iter().map(|r| r.get(0)).collect())
}

pub async fn remove_layer_from_map<C: GenericClient + Sync>(c: &C, map_id: i32, layer_id: i32) -> DbResult<()> {
    let rows = c
        .query("SELECT layer_id, idx FROM maps_layers WHERE map_id = $1 ORDER BY idx", &[&map_id])
        .await
        .map_err(e2s)?;
    let mut layers: Vec<i32> = rows.iter().map(|r| r.get(0)).collect();
    if let Some(pos) = layers.iter().position(|l| *l == layer_id) {
        layers.remove(pos);
    }
    c.execute("DELETE FROM maps_layers WHERE map_id = $1", &[&map_id]).await.map_err(e2s)?;
    for (i, l) in layers.iter().enumerate() {
        let i = i as i32;
        c.execute("INSERT INTO maps_layers (map_id, layer_id, idx) VALUES ($1, $2, $3)", &[&map_id, l, &i])
            .await
            .map_err(e2s)?;
    }
    Ok(())
}

/// Existence check used by the user group id resolver.
pub async fn group_exists<C: GenericClient + Sync>(c: &C, id: i32) -> DbResult<bool> {
    Ok(c.query_opt("SELECT 1 FROM usergroups WHERE id = $1", &[&id]).await.map_err(e2s)?.is_some())
}

