/// Resolves the user group ids read from `User.userGroups` like the
/// original's id resolver (`loadById` with READ check).
async fn check_group_refs<C: tokio_postgres::GenericClient + Sync>(c: &C, ev: &Evaluator, refs: &[i32]) -> Result<(), String> {
