//! End-to-end test: starts the service binary on the database given by
//! `DATABASE_URL`, loads `tests/data/seed.sql` and checks the REST API.
//!
//! It only runs when that database has `schema.sql` loaded and holds no data
//! (it is emptied again at the end); otherwise it is skipped.

use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};

const SEED: &str = include_str!("data/seed.sql");
const EMPTY: &str = "DO $$ DECLARE r record; BEGIN \
  FOR r IN SELECT tablename FROM pg_tables WHERE schemaname='public' LOOP \
    EXECUTE 'TRUNCATE TABLE public.' || quote_ident(r.tablename) || ' CASCADE'; \
  END LOOP; END $$;";

struct Server(Child);
impl Drop for Server {
    fn drop(&mut self) {
        let _ = self.0.kill();
        let _ = self.0.wait();
    }
}

struct Resp {
    status: u16,
    body: String,
}

impl Resp {
    fn json(&self) -> serde_json::Value {
        serde_json::from_str(&self.body).unwrap_or(serde_json::Value::Null)
    }
}

fn request(port: u16, method: &str, path: &str, user: Option<(&str, &str)>, body: Option<&str>) -> Resp {
    use base64::Engine;
    let mut s = TcpStream::connect(("127.0.0.1", port)).expect("connect");
    s.set_read_timeout(Some(Duration::from_secs(30))).unwrap();
    let mut req = format!("{} {} HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n", method, path);
    if let Some((u, p)) = user {
        let t = base64::engine::general_purpose::STANDARD.encode(format!("{}:{}", u, p));
        req.push_str(&format!("Authorization: Basic {}\r\n", t));
    }
    let b = body.unwrap_or("");
    if body.is_some() {
        req.push_str("Content-Type: application/json\r\n");
    }
    req.push_str(&format!("Content-Length: {}\r\n\r\n{}", b.len(), b));
    s.write_all(req.as_bytes()).unwrap();
    let mut raw = Vec::new();
    s.read_to_end(&mut raw).unwrap();
    let text = String::from_utf8_lossy(&raw).to_string();
    let status: u16 = text.split(' ').nth(1).and_then(|c| c.parse().ok()).unwrap_or(0);
    let (head, body) = text.split_once("\r\n\r\n").unwrap_or((&text, ""));
    let body = if head.to_ascii_lowercase().contains("transfer-encoding: chunked") {
        dechunk(body)
    } else {
        body.to_string()
    };
    Resp { status, body }
}

fn dechunk(mut s: &str) -> String {
    let mut out = String::new();
    loop {
        let (len, rest) = match s.split_once("\r\n") {
            Some(x) => x,
            None => break,
        };
        let n = usize::from_str_radix(len.trim(), 16).unwrap_or(0);
        if n == 0 {
            break;
        }
        out.push_str(&rest[..n]);
        s = &rest[n + 2..];
    }
    out
}

fn ids(v: &serde_json::Value) -> Vec<i64> {
    let mut out: Vec<i64> = v.as_array().map(|a| a.iter().filter_map(|o| o["id"].as_i64()).collect()).unwrap_or_default();
    out.sort();
    out
}

#[tokio::test(flavor = "multi_thread")]
async fn rest_api_against_database() {
    let url = match std::env::var("DATABASE_URL") {
        Ok(u) => u,
        Err(_) => {
            eprintln!("DATABASE_URL not set: skipping");
            return;
        }
    };
    let (client, conn) = match tokio_postgres::connect(&url, tokio_postgres::NoTls).await {
        Ok(c) => c,
        Err(e) => {
            eprintln!("database not reachable ({}): skipping", e);
            return;
        }
    };
    tokio::spawn(conn);
    let count = |sql: &'static str| {
        let client = &client;
        async move { client.query_one(sql, &[]).await.map(|r| r.get::<_, i64>(0)) }
    };
    let rows = count("SELECT (SELECT count(*) FROM persons) + (SELECT count(*) FROM roles) + (SELECT count(*) FROM hibernate_sequences)").await;
    match rows {
        Ok(0) => {}
        Ok(_) => {
            eprintln!("database is not empty: skipping");
            return;
        }
        Err(e) => {
            eprintln!("schema not loaded ({}): skipping", e);
            return;
        }
    }
    client.batch_execute(SEED).await.expect("seed");

    let port = TcpListener::bind("127.0.0.1:0").unwrap().local_addr().unwrap().port();
    let _server = Server(
        Command::new(env!("CARGO_BIN_EXE_shogun-rest"))
            .env("DATABASE_URL", &url)
            .env("PORT", port.to_string())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .expect("start service"),
    );
    let start = Instant::now();
    while TcpStream::connect(("127.0.0.1", port)).is_err() {
        assert!(start.elapsed() < Duration::from_secs(60), "service did not start");
        std::thread::sleep(Duration::from_millis(100));
    }

    let result = std::panic::AssertUnwindSafe(async {
        let admin = Some(("admin", "shogun"));
        let user = Some(("user", "shogun"));

        // security
        let r = request(port, "GET", "/rest/roles", None, None);
        assert_eq!(r.status, 401);
        assert_eq!(request(port, "GET", "/rest/roles", Some(("admin", "wrong")), None).status, 401);
        assert_eq!(request(port, "GET", "/rest/roles", Some(("inactive", "shogun")), None).status, 401);
        assert_eq!(request(port, "GET", "/rest/roles", Some(("norole", "shogun")), None).status, 401);
        assert_eq!(request(port, "GET", "/rest/roles", Some(("grouprole", "shogun")), None).status, 200);
        assert_eq!(request(port, "GET", "/rest/users", Some(("other", "shogun")), None).status, 403);

        // lists filtered by READ
        let r = request(port, "GET", "/rest/roles", user, None);
        assert_eq!(ids(&r.json()), vec![1, 2, 7, 14]);
        let r = request(port, "GET", "/rest/users", user, None);
        assert_eq!(ids(&r.json()), vec![4, 8, 10]);
        let r = request(port, "GET", "/rest/layers", user, None);
        assert_eq!(ids(&r.json()), vec![50, 51, 52, 54, 55]);
        let r = request(port, "GET", "/rest/groups", user, None);
        assert_eq!(r.status, 500, "group 11 holds a permission for itself (original fails)");

        // single entities and embedding
        let r = request(port, "GET", "/rest/layers/51", admin, None);
        let j = r.json();
        assert_eq!(j["source"]["tileGrid"]["tileGridExtent"]["id"], 20);
        assert_eq!(j["source"]["type"], "TileWMS");
        let r = request(port, "GET", "/rest/users/4", admin, None);
        let j = r.json();
        assert!(j.get("password").is_none());
        assert_eq!(j["birthday"], "1990-05-17");
        assert_eq!(request(port, "GET", "/rest/users/3", user, None).status, 404);
        assert_eq!(request(port, "GET", "/rest/users/abc", admin, None).status, 400);
        let r = request(port, "GET", "/rest/layerappearances/40", admin, None);
        assert_eq!(r.json()["properties"]["a"], 1);
        assert_eq!(r.json()["properties"]["b"], true);

        // output:only and filters
        let r = request(port, "GET", "/rest/roles?output:only=name", admin, None);
        assert!(r.json().as_array().unwrap().iter().all(|o| o["id"].is_null()));
        assert_eq!(request(port, "GET", "/rest/layerdatasources?output:only=id", admin, None).status, 500);
        let r = request(port, "GET", "/rest/users/filter?active=yes&output:only=accountName", admin, None);
        assert_eq!(r.json().as_array().unwrap().len(), 6);
        let r = request(port, "GET", "/rest/roles/filter?name=ROLE_USER&name=ROLE_ADMIN", admin, None);
        assert_eq!(ids(&r.json()), vec![1, 2]);

        // create
        let r = request(port, "POST", "/rest/roles", admin, Some(r#"{"name":"ROLE_NEW"}"#));
        assert_eq!(r.status, 201);
        assert_eq!(r.json()["id"], 101);
        assert_eq!(request(port, "POST", "/rest/roles", user, Some(r#"{"name":"ROLE_U"}"#)).status, 400);
        assert_eq!(request(port, "POST", "/rest/layerdatasources", admin, Some(r#"{"name":"x"}"#)).status, 400);
        assert_eq!(request(port, "POST", "/rest/layers", admin, Some(r#"{"name":"x","source":{"id":30}}"#)).status, 400);
        let r = request(port, "POST", "/rest/layers", admin, Some(r#"{"name":"x","appearance":{"name":"a"}}"#));
        assert_eq!(r.status, 201);
        assert_eq!((r.json()["id"].clone(), r.json()["appearance"]["id"].clone()), (102.into(), 103.into()));
        let next: i64 = client.query_one("SELECT next_val FROM hibernate_sequences", &[]).await.unwrap().get(0);
        assert_eq!(next, 103);

        // update
        let r = request(port, "PUT", "/rest/layerdatasources/31", admin, Some(r#"{"id":31,"name":"renamed","width":"1"}"#));
        assert_eq!(r.status, 200);
        assert_eq!(r.json()["width"], 1);
        assert_eq!(request(port, "PUT", "/rest/roles/7", admin, Some(r#"{"id":8}"#)).status, 400);
        assert_eq!(request(port, "PUT", "/rest/roles/7", user, Some(r#"{"id":7,"description":"x"}"#)).status, 200);
        assert_eq!(request(port, "PUT", "/rest/roles/1", user, Some(r#"{"id":1,"description":"x"}"#)).status, 404);
        let r = request(port, "PUT", "/rest/users/4", admin, Some(r#"{"id":4,"userGroups":[5]}"#));
        assert_eq!(r.json()["userGroups"], serde_json::json!([5]));
        let n: i64 = client
            .query_one("SELECT count(*) FROM user_usergroup WHERE user_id = 4", &[])
            .await
            .unwrap()
            .get(0);
        assert_eq!(n, 1);

        // delete
        assert_eq!(request(port, "DELETE", "/rest/roles/2", admin, None).status, 404);
        assert_eq!(request(port, "DELETE", "/rest/layers/55", user, None).status, 204);
        assert_eq!(request(port, "DELETE", "/rest/layers/50", user, None).status, 404);
        let n: i64 = client.query_one("SELECT count(*) FROM layers WHERE id = 55", &[]).await.unwrap().get(0);
        assert_eq!(n, 0);
    });
    let outcome = futures_catch(result).await;
    client.batch_execute(EMPTY).await.expect("empty database again");
    if let Err(p) = outcome {
        std::panic::resume_unwind(p);
    }
}

