    f: std::panic::AssertUnwindSafe<F>,
) -> Result<(), Box<dyn std::any::Any + Send>> {
    // run the checks on this task; a panic is caught so the database can be
    // emptied before the failure is reported
    let handle = tokio::task::block_in_place(|| {
        tokio::runtime::Handle::current().block_on(async { std::panic::AssertUnwindSafe(f).catch_unwind_compat().await })
    });
    handle
}

trait CatchUnwindCompat: std::future::Future + Sized {
