        m=random.choice(["GET","GET","GETL","FILTER","POST","PUT","PUT","DELETE"])
        body=None; path=None
        if m in ("POST","PUT"):
            body={}
            for f in random.sample(FIELDS[r], random.randint(1,3)):
                body[f]=random.choice(NESTED[f]) if (f in NESTED and random.random()<0.8) else random.choice(VALS)
            if m=="POST":
                body.pop("id",None); path=f"/rest/{r}"
            else:
                i=random.choice(created[r]); body["id"]=i; path=f"/rest/{r}/{i}"
        elif m=="DELETE":
            path=f"/rest/{r}/{random.choice(created[r])}"
        elif m=="GET":
            path=f"/rest/{r}/{random.choice(created[r])}"
        elif m=="GETL":
            m="GET"; path=f"/rest/{r}"
