    if not dbok or not all(x[6] for x in steps):
        fails+=1
        print("FAIL sequence", s)
        for x in steps: print("   ", "ok " if x[6] else "BAD", x[0], x[1], x[2], (x[3] or "")[:120], x[4], x[5], "" if x[6] else ("\n      ref:"+x[7]+"\n      port:"+x[8]))
