import json, random, sys
random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 9)
ENT={"users":[3,4,8,9,10,12,15],"groups":[5,6,11,13],"roles":[1,2,7,14],"layers":[50,51,52,53,54,55,56],"layerappearances":[40,41],"layerdatasources":[30,31,32,33,34]}
ALL=[i for v in ENT.values() for i in v]
PERMS=["READ","UPDATE","DELETE","CREATE","ADMIN"]
C=[]
for i in range(int(sys.argv[2]) if len(sys.argv)>2 else 200):
    sql=["delete from userpermissions; delete from grouppermissions; insert into permissioncollections(id) values (90),(91),(92),(93)"]
    for pc in (90,91,92,93):
        for p in random.sample(PERMS, random.randint(1,3)):
            sql.append(f"insert into permissioncollections_permissions values ({pc},'{p}')")
    used=set()
    for _ in range(random.randint(2,10)):
        e=random.choice(ALL)
        if random.random()<0.5:
            k=random.choice([4,8,12]); 
            if ("u",e,k) in used: continue
            used.add(("u",e,k)); sql.append(f"insert into userpermissions values ({e},{random.choice([90,91,92,93])},{k})")
        else:
            k=random.choice([5,6,11,13])
            if ("g",e,k) in used: continue
            used.add(("g",e,k)); sql.append(f"insert into grouppermissions values ({e},{random.choice([90,91,92,93])},{k})")
    r=random.choice(list(ENT)); u=random.choice(["user","editor","grouprole"]); e=random.choice(ENT[r])
    m=random.choice(["GET","GETL","PUT","DELETE","SUB"])
    d={"user":u,"sql":"; ".join(sql)}
    if m=="GET": d.update(method="GET",path=f"/rest/{r}/{e}")
    elif m=="GETL": d.update(method="GET",path=f"/rest/{r}")
    elif m=="PUT":
        body={"id":e}
        body[{"users":"firstName","groups":"name","roles":"description","layers":"description","layerappearances":"name","layerdatasources":"name"}[r]]="changed"
        if r=="users" and random.random()<0.5: body["userGroups"]=random.sample([5,6,11,13],2)
        d.update(method="PUT",path=f"/rest/{r}/{e}",body=body)
    elif m=="DELETE": d.update(method="DELETE",path=f"/rest/{r}/{e}")
    else:
        d.update(method="GET",path=random.choice([f"/rest/users/{random.choice(ENT['users'])}/userGroups",f"/rest/groups/{random.choice(ENT['groups'])}/users"]))
    C.append(d)
json.dump(C,open("cases_pfuzz.json","w"))
print(len(C))
EOF
